107|static inst* block_take(block* b) {
108|  if (b->first == 0) return 0;
109|  inst* i = b->first;
110|  if (i->next) {
111|    i->next->prev = 0;
112|    b->first = i->next;
113|    i->next = 0;
114|  } else {
115|    b->first = 0;
116|    b->last = 0;
117|  }
118|  return i;
