121|block gen_location(location loc, struct locfile* l, block b) {
122|  for (inst* i = b.first; i; i = i->next) {
123|    if (i->source.start == UNKNOWN_LOCATION.start &&
124|        i->source.end == UNKNOWN_LOCATION.end) {
125|      i->source = loc;
126|      i->locfile = locfile_retain(l);
127|    }
128|  }
129|  return b;
