291|// Count a call site's actual params
292|static int block_count_actuals(block b) {
293|  int args = 0;
294|  for (inst* i = b.first; i; i = i->next) {
295|    switch (i->op) {
296|    default: assert(0 && "Unknown function type"); break;
297|    case CLOSURE_CREATE:
298|    case CLOSURE_PARAM:
299|    case CLOSURE_CREATE_C:
300|      args++;
301|      break;
302|    }
303|  }
304|  return args;
