358|static int block_bind_each(block binder, block body, int bindflags) {
359|  assert(block_has_only_binders(binder, bindflags));
360|  bindflags |= OP_HAS_BINDING;
361|  int nrefs = 0;
362|  for (inst* curr = binder.first; curr; curr = curr->next) {
363|    nrefs += block_bind_subblock(inst_block(curr), body, bindflags, 0);
364|  }
365|  return nrefs;
