373|block block_bind_library(block binder, block body, int bindflags, const char *libname) {
374|  bindflags |= OP_HAS_BINDING;
375|  int matchlen = (libname == NULL) ? 0 : strlen(libname);
376|  char *matchname = jv_mem_alloc(matchlen+2+1);
377|  matchname[0] = '\0';
378|  if (libname != NULL && libname[0] != '\0') {
379|    strcpy(matchname,libname);
380|    strcpy(matchname+matchlen, "::");
381|    matchlen += 2;
382|  }
383|  assert(block_has_only_binders(binder, bindflags));
384|  for (inst *curr = binder.last; curr; curr = curr->prev) {
385|    int bindflags2 = bindflags;
386|    char* cname = curr->symbol;
387|    char* tname = jv_mem_alloc(strlen(curr->symbol)+matchlen+1);
388|    strcpy(tname, matchname);
389|    strcpy(tname+matchlen, curr->symbol);
390|
391|    // Ew
392|    if ((opcode_describe(curr->op)->flags & (OP_HAS_VARIABLE | OP_HAS_CONSTANT)))
393|      bindflags2 = OP_HAS_VARIABLE | OP_HAS_BINDING;
394|
395|    // This mutation is ugly, even if we undo it
396|    curr->symbol = tname;
397|    block_bind_subblock(inst_block(curr), body, bindflags2, 0);
398|    curr->symbol = cname;
399|    free(tname);
400|  }
401|  free(matchname);
402|  return body; // We don't return a join because we don't want those sticking around...
