420|// Binds a sequence of binders, which *must not* already be bound to each other,
421|// to body, throwing away unreferenced defs
422|block block_bind_referenced(block binder, block body, int bindflags) {
423|  assert(block_has_only_binders(binder, bindflags));
424|  bindflags |= OP_HAS_BINDING;
425|
426|  inst* curr;
427|  while ((curr = block_take_last(&binder))) {
428|    block b = inst_block(curr);
429|    if (block_bind_subblock(b, body, bindflags, 0) == 0) {
430|      block_free(b);
431|    } else {
432|      body = BLOCK(b, body);
433|    }
434|  }
435|  return body;
