501|jv block_list_funcs(block body, int omit_underscores) {
502|  jv funcs = jv_object(); // Use the keys for set semantics.
503|  for (inst *pos = body.first; pos != NULL; pos = pos->next) {
504|    if (pos->op == CLOSURE_CREATE || pos->op == CLOSURE_CREATE_C) {
505|      if (pos->symbol != NULL && (!omit_underscores || pos->symbol[0] != '_')) {
506|        funcs = jv_object_set(funcs, jv_string_fmt("%s/%i", pos->symbol, pos->nformals), jv_null());
507|      }
508|    }
509|  }
510|  return jv_keys_unsorted(funcs);
