549|block gen_function(const char* name, block formals, block body) {
550|  inst* i = inst_new(CLOSURE_CREATE);
551|  int nformals = 0;
552|  for (inst* i = formals.last; i; i = i->prev) {
553|    nformals++;
554|    i->nformals = 0;
555|    if (i->op == CLOSURE_PARAM_REGULAR) {
556|      i->op = CLOSURE_PARAM;
557|      body = gen_var_binding(gen_call(i->symbol, gen_noop()), i->symbol, body);
558|    }
559|    block_bind_subblock(inst_block(i), body, OP_IS_CALL_PSEUDO | OP_HAS_BINDING, 0);
560|  }
561|  i->subfn = body;
562|  i->symbol = strdup(name);
