1101|static uint16_t nesting_level(struct bytecode* bc, inst* target) {
1102|  uint16_t level = 0;
1103|  assert(bc && target && target->compiled);
1104|  while (bc && target->compiled != bc) {
1105|    level++;
1106|    bc = bc->parent;
1107|  }
1108|  assert(bc && bc == target->compiled);
1109|  return level;
