1235|static int compile(struct bytecode* bc, block b, struct locfile* lf, jv args, jv *env) {
1236|  int errors = 0;
1237|  int pos = 0;
1238|  int var_frame_idx = 0;
1239|  bc->nsubfunctions = 0;
1240|  errors += expand_call_arglist(&b, args, env);
1241|  b = BLOCK(b, gen_op_simple(RET));
1242|  jv localnames = jv_array();
1243|  for (inst* curr = b.first; curr; curr = curr->next) {
1244|    if (!curr->next) assert(curr == b.last);
1245|    int length = opcode_describe(curr->op)->length;
1246|    if (curr->op == CALL_JQ) {
1247|      for (inst* arg = curr->arglist.first; arg; arg = arg->next) {
1248|        length += 2;
1249|      }
1250|    }
1251|    pos += length;
1252|    curr->bytecode_pos = pos;
1253|    curr->compiled = bc;
1254|
1255|    assert(curr->op != CLOSURE_REF && curr->op != CLOSURE_PARAM);
1256|
1257|    if ((opcode_describe(curr->op)->flags & OP_HAS_VARIABLE) &&
1258|        curr->bound_by == curr) {
1259|      curr->imm.intval = var_frame_idx++;
1260|      localnames = jv_array_append(localnames, jv_string(curr->symbol));
1261|    }
1262|
1263|    if (curr->op == CLOSURE_CREATE) {
1264|      assert(curr->bound_by == curr);
1265|      curr->imm.intval = bc->nsubfunctions++;
1266|    }
1267|    if (curr->op == CLOSURE_CREATE_C) {
1268|      assert(curr->bound_by == curr);
1269|      int idx = bc->globals->ncfunctions++;
1270|      bc->globals->cfunc_names = jv_array_append(bc->globals->cfunc_names,
1271|                                                 jv_string(curr->symbol));
1272|      bc->globals->cfunctions[idx] = *curr->imm.cfunc;
1273|      curr->imm.intval = idx;
1274|    }
1275|  }
1276|  if (pos > 0xFFFF) {
1277|    // too long for program counter to fit in uint16_t
1278|    locfile_locate(lf, UNKNOWN_LOCATION,
1279|        "function compiled to %d bytes which is too long", pos);
1280|    errors++;
1281|  }
1282|  bc->codelen = pos;
1283|  bc->debuginfo = jv_object_set(bc->debuginfo, jv_string("locals"), localnames);
1284|  if (bc->nsubfunctions && !errors) {
1285|    bc->subfunctions = jv_mem_calloc(bc->nsubfunctions, sizeof(struct bytecode*));
1286|    for (inst* curr = b.first; curr; curr = curr->next) {
1287|      if (curr->op == CLOSURE_CREATE) {
1288|        struct bytecode* subfn = jv_mem_alloc(sizeof(struct bytecode));
1289|        bc->subfunctions[curr->imm.intval] = subfn;
1290|        subfn->globals = bc->globals;
1291|        subfn->parent = bc;
1292|        subfn->nclosures = 0;
1293|        subfn->debuginfo = jv_object_set(jv_object(), jv_string("name"), jv_string(curr->symbol));
1294|        jv params = jv_array();
1295|        for (inst* param = curr->arglist.first; param; param = param->next) {
1296|          assert(param->op == CLOSURE_PARAM);
1297|          assert(param->bound_by == param);
1298|          param->imm.intval = subfn->nclosures++;
1299|          param->compiled = subfn;
1300|          params = jv_array_append(params, jv_string(param->symbol));
1301|        }
1302|        subfn->debuginfo = jv_object_set(subfn->debuginfo, jv_string("params"), params);
1303|        errors += compile(subfn, curr->subfn, lf, args, env);
1304|        curr->subfn = gen_noop();
1305|      }
1306|    }
1307|  } else {
1308|    bc->nsubfunctions = 0;
1309|    bc->subfunctions = 0;
1310|  }
1311|  uint16_t* code = jv_mem_calloc(bc->codelen, sizeof(uint16_t));
1312|  bc->code = code;
1313|  pos = 0;
1314|  jv constant_pool = jv_array();
1315|  int maxvar = -1;
1316|  if (!errors) for (inst* curr = b.first; curr; curr = curr->next) {
1317|    const struct opcode_description* op = opcode_describe(curr->op);
1318|    if (op->length == 0)
1319|      continue;
1320|    code[pos++] = curr->op;
1321|    assert(curr->op != CLOSURE_REF && curr->op != CLOSURE_PARAM);
1322|    if (curr->op == CALL_BUILTIN) {
1323|      assert(curr->bound_by->op == CLOSURE_CREATE_C);
1324|      assert(!curr->arglist.first);
1325|      code[pos++] = (uint16_t)curr->imm.intval;
1326|      code[pos++] = curr->bound_by->imm.intval;
1327|    } else if (curr->op == CALL_JQ) {
1328|      assert(curr->bound_by->op == CLOSURE_CREATE ||
1329|             curr->bound_by->op == CLOSURE_PARAM);
1330|      code[pos++] = (uint16_t)curr->imm.intval;
1331|      code[pos++] = nesting_level(bc, curr->bound_by);
1332|      code[pos++] = curr->bound_by->imm.intval |
1333|        (curr->bound_by->op == CLOSURE_CREATE ? ARG_NEWCLOSURE : 0);
1334|      for (inst* arg = curr->arglist.first; arg; arg = arg->next) {
1335|        assert(arg->op == CLOSURE_REF && arg->bound_by->op == CLOSURE_CREATE);
1336|        code[pos++] = nesting_level(bc, arg->bound_by);
1337|        code[pos++] = arg->bound_by->imm.intval | ARG_NEWCLOSURE;
1338|      }
1339|    } else if ((op->flags & OP_HAS_CONSTANT) && (op->flags & OP_HAS_VARIABLE)) {
1340|      // STORE_GLOBAL: constant global, basically
1341|      code[pos++] = jv_array_length(jv_copy(constant_pool));
1342|      constant_pool = jv_array_append(constant_pool, jv_copy(curr->imm.constant));
1343|      code[pos++] = nesting_level(bc, curr->bound_by);
1344|      uint16_t var = (uint16_t)curr->bound_by->imm.intval;
1345|      code[pos++] = var;
1346|      if (var > maxvar) maxvar = var;
1347|    } else if (op->flags & OP_HAS_CONSTANT) {
1348|      code[pos++] = jv_array_length(jv_copy(constant_pool));
1349|      constant_pool = jv_array_append(constant_pool, jv_copy(curr->imm.constant));
1350|    } else if (op->flags & OP_HAS_VARIABLE) {
1351|      code[pos++] = nesting_level(bc, curr->bound_by);
1352|      uint16_t var = (uint16_t)curr->bound_by->imm.intval;
1353|      code[pos++] = var;
1354|      if (var > maxvar) maxvar = var;
1355|    } else if (op->flags & OP_HAS_BRANCH) {
1356|      assert(curr->imm.target->bytecode_pos != -1);
1357|      assert(curr->imm.target->bytecode_pos > pos); // only forward branches
1358|      code[pos] = curr->imm.target->bytecode_pos - (pos + 1);
1359|      pos++;
1360|    } else if (op->length > 1) {
1361|      assert(0 && "codegen not implemented for this operation");
1362|    }
1363|  }
1364|  bc->constants = constant_pool;
1365|  bc->nlocals = maxvar + 2; // FIXME: frames of size zero?
1366|  block_free(b);
1367|  return errors;
1368|}
