94|jv binop_plus(jv a, jv b) {
95|  if (jv_get_kind(a) == JV_KIND_NULL) {
96|    jv_free(a);
97|    return b;
98|  } else if (jv_get_kind(b) == JV_KIND_NULL) {
99|    jv_free(b);
100|    return a;
101|  } else if (jv_get_kind(a) == JV_KIND_NUMBER && jv_get_kind(b) == JV_KIND_NUMBER) {
102|    jv r = jv_number(jv_number_value(a) +
103|                     jv_number_value(b));
104|    jv_free(a);
105|    jv_free(b);
106|    return r;
107|  } else if (jv_get_kind(a) == JV_KIND_STRING && jv_get_kind(b) == JV_KIND_STRING) {
108|    return jv_string_concat(a, b);
109|  } else if (jv_get_kind(a) == JV_KIND_ARRAY && jv_get_kind(b) == JV_KIND_ARRAY) {
110|    return jv_array_concat(a, b);
111|  } else if (jv_get_kind(a) == JV_KIND_OBJECT && jv_get_kind(b) == JV_KIND_OBJECT) {
112|    return jv_object_merge(a, b);
113|  } else {
114|    return type_error2(a, b, "cannot be added");
115|  }
