572|static jv f_format(jq_state *jq, jv input, jv fmt) {
573|  if (jv_get_kind(fmt) != JV_KIND_STRING) {
574|    jv_free(input);
575|    return type_error(fmt, "is not a valid format");
576|  }
577|  const char* fmt_s = jv_string_value(fmt);
578|  if (!strcmp(fmt_s, "json")) {
579|    jv_free(fmt);
580|    return jv_dump_string(input, 0);
581|  } else if (!strcmp(fmt_s, "text")) {
582|    jv_free(fmt);
583|    return f_tostring(jq, input);
584|  } else if (!strcmp(fmt_s, "csv") || !strcmp(fmt_s, "tsv")) {
585|    const char *quotes, *sep, *escapings;
586|    const char *msg;
587|    if (!strcmp(fmt_s, "csv")) {
588|      msg = "cannot be csv-formatted, only array";
589|      quotes = "\"";
590|      sep = ",";
591|      escapings = "\"\"\"\0";
592|    } else {
593|      msg = "cannot be tsv-formatted, only array";
594|      assert(!strcmp(fmt_s, "tsv"));
595|      quotes = "";
596|      sep = "\t";
597|      escapings = "\t\\t\0\r\\r\0\n\\n\0\\\\\\\0";
598|    }
599|    jv_free(fmt);
600|    if (jv_get_kind(input) != JV_KIND_ARRAY)
601|      return type_error(input, msg);
602|    jv line = jv_string("");
603|    jv_array_foreach(input, i, x) {
604|      if (i) line = jv_string_append_str(line, sep);
605|      switch (jv_get_kind(x)) {
606|      case JV_KIND_NULL:
607|        /* null rendered as empty string */
608|        jv_free(x);
609|        break;
610|      case JV_KIND_TRUE:
611|      case JV_KIND_FALSE:
612|        line = jv_string_concat(line, jv_dump_string(x, 0));
613|        break;
614|      case JV_KIND_NUMBER:
615|        if (jv_number_value(x) != jv_number_value(x)) {
616|          /* NaN, render as empty string */
617|          jv_free(x);
618|        } else {
619|          line = jv_string_concat(line, jv_dump_string(x, 0));
620|        }
621|        break;
622|      case JV_KIND_STRING: {
623|        line = jv_string_append_str(line, quotes);
624|        line = jv_string_concat(line, escape_string(x, escapings));
625|        line = jv_string_append_str(line, quotes);
626|        break;
627|      }
628|      default:
629|        jv_free(input);
630|        jv_free(line);
631|        return type_error(x, "is not valid in a csv row");
632|      }
633|    }
634|    jv_free(input);
635|    return line;
636|  } else if (!strcmp(fmt_s, "html")) {
637|    jv_free(fmt);
638|    return escape_string(f_tostring(jq, input), "&&amp;\0<&lt;\0>&gt;\0'&apos;\0\"&quot;\0");
639|  } else if (!strcmp(fmt_s, "uri")) {
640|    jv_free(fmt);
641|    input = f_tostring(jq, input);
642|
643|    int unreserved[128] = {0};
644|    const char* p = CHARS_ALPHANUM "-_.~";
645|    while (*p) unreserved[(int)*p++] = 1;
646|
647|    jv line = jv_string("");
648|    const char* s = jv_string_value(input);
649|    for (int i=0; i<jv_string_length_bytes(jv_copy(input)); i++) {
650|      unsigned ch = (unsigned)(unsigned char)*s;
651|      if (ch < 128 && unreserved[ch]) {
652|        line = jv_string_append_buf(line, s, 1);
653|      } else {
654|        line = jv_string_concat(line, jv_string_fmt("%%%02X", ch));
655|      }
656|      s++;
657|    }
658|    jv_free(input);
659|    return line;
660|  } else if (!strcmp(fmt_s, "urid")) {
661|    jv_free(fmt);
662|    input = f_tostring(jq, input);
663|
664|    jv line = jv_string("");
665|    const char *errmsg =  "is not a valid uri encoding";
666|    const char *s = jv_string_value(input);
667|    while (*s) {
668|      if (*s != '%') {
669|        line = jv_string_append_buf(line, s++, 1);
670|      } else {
671|        unsigned char unicode[4] = {0};
672|        int b = 0;
673|        // check leading bits of first octet to determine length of unicode character
674|        // (https://datatracker.ietf.org/doc/html/rfc3629#section-3)
675|        while (b == 0 || (b < 4 && unicode[0] >> 7 & 1 && unicode[0] >> (7-b) & 1)) {
676|          if (*(s++) != '%') {
677|            jv_free(line);
678|            return type_error(input, errmsg);
679|          }
680|          for (int i=0; i<2; i++) {
681|            unicode[b] <<= 4;
682|            char c = *(s++);
683|            if ('0' <= c && c <= '9') unicode[b] |= c - '0';
684|            else if ('a' <= c && c <= 'f') unicode[b] |= c - 'a' + 10;
685|            else if ('A' <= c && c <= 'F') unicode[b] |= c - 'A' + 10;
686|            else {
687|              jv_free(line);
688|              return type_error(input, errmsg);
689|            }
690|          }
691|          b++;
692|        }
693|        if (!jvp_utf8_is_valid((const char *)unicode, (const char *)unicode+b)) {
694|          jv_free(line);
695|          return type_error(input, errmsg);
696|        }
697|        line = jv_string_append_buf(line, (const char *)unicode, b);
698|      }
699|    }
700|    jv_free(input);
701|    return line;
702|  } else if (!strcmp(fmt_s, "sh")) {
703|    jv_free(fmt);
704|    if (jv_get_kind(input) != JV_KIND_ARRAY)
705|      input = jv_array_set(jv_array(), 0, input);
706|    jv line = jv_string("");
707|    jv_array_foreach(input, i, x) {
708|      if (i) line = jv_string_append_str(line, " ");
709|      switch (jv_get_kind(x)) {
710|      case JV_KIND_NULL:
711|      case JV_KIND_TRUE:
712|      case JV_KIND_FALSE:
713|      case JV_KIND_NUMBER:
714|        line = jv_string_concat(line, jv_dump_string(x, 0));
715|        break;
716|
717|      case JV_KIND_STRING: {
718|        line = jv_string_append_str(line, "'");
719|        line = jv_string_concat(line, escape_string(x, "''\\''\0"));
720|        line = jv_string_append_str(line, "'");
721|        break;
722|      }
723|
724|      default:
725|        jv_free(input);
726|        jv_free(line);
727|        return type_error(x, "can not be escaped for shell");
728|      }
729|    }
730|    jv_free(input);
731|    return line;
732|  } else if (!strcmp(fmt_s, "base64")) {
733|    jv_free(fmt);
734|    input = f_tostring(jq, input);
735|    jv line = jv_string("");
736|    const unsigned char* data = (const unsigned char*)jv_string_value(input);
737|    int len = jv_string_length_bytes(jv_copy(input));
738|    for (int i=0; i<len; i+=3) {
739|      uint32_t code = 0;
740|      int n = len - i >= 3 ? 3 : len-i;
741|      for (int j=0; j<3; j++) {
742|        code <<= 8;
743|        code |= j < n ? (unsigned)data[i+j] : 0;
744|      }
745|      char buf[4];
746|      for (int j=0; j<4; j++) {
747|        buf[j] = BASE64_ENCODE_TABLE[(code >> (18 - j*6)) & 0x3f];
