757|    input = f_tostring(jq, input);
758|    const unsigned char* data = (const unsigned char*)jv_string_value(input);
759|    int len = jv_string_length_bytes(jv_copy(input));
760|    size_t decoded_len = (3 * (size_t)len) / 4; // 3 usable bytes for every 4 bytes of input
761|    char *result = jv_mem_calloc(decoded_len, sizeof(char));
762|    memset(result, 0, decoded_len * sizeof(char));
763|    uint32_t ri = 0;
764|    int input_bytes_read=0;
765|    uint32_t code = 0;
766|    for (int i=0; i<len && data[i] != '='; i++) {
767|      if (BASE64_DECODE_TABLE[data[i]] == BASE64_INVALID_ENTRY) {
768|        free(result);
769|        return type_error(input, "is not valid base64 data");
770|      }
771|
772|      code <<= 6;
773|      code |= BASE64_DECODE_TABLE[data[i]];
774|      input_bytes_read++;
775|
776|      if (input_bytes_read == 4) {
777|        result[ri++] = (code >> 16) & 0xFF;
778|        result[ri++] = (code >> 8) & 0xFF;
779|        result[ri++] = code & 0xFF;
780|        input_bytes_read = 0;
781|        code = 0;
782|      }
783|    }
784|    if (input_bytes_read == 3) {
785|      result[ri++] = (code >> 10) & 0xFF;
786|      result[ri++] = (code >> 2) & 0xFF;
787|    } else if (input_bytes_read == 2) {
788|      result[ri++] = (code >> 4) & 0xFF;
789|    } else if (input_bytes_read == 1) {
790|      free(result);
791|      return type_error(input, "trailing base64 byte found");
792|    }
793|
794|    jv line = jv_string_sized(result, ri);
795|    jv_free(input);
796|    free(result);
797|    return line;
798|  } else {
799|    jv_free(input);
800|    return jv_invalid_with_msg(jv_string_concat(fmt, jv_string(" is not a valid format")));
