838|/*
839| * Assuming the input array is sorted, bsearch/1 returns
840| * the index of the target if the target is in the input array; and otherwise
841| * (-1 - ix), where ix is the insertion point that would leave the array sorted.
842| * If the input is not sorted, bsearch will terminate but with irrelevant results.
843| */
844|static jv f_bsearch(jq_state *jq, jv input, jv target) {
845|  if (jv_get_kind(input) != JV_KIND_ARRAY) {
846|    jv_free(target);
847|    return type_error(input, "cannot be searched from");
848|  }
849|  int start = 0;
850|  int end = jv_array_length(jv_copy(input));
851|  jv answer = jv_invalid();
852|  while (start < end) {
853|    int mid = start + (end - start) / 2;
854|    int result = jv_cmp(jv_copy(target), jv_array_get(jv_copy(input), mid));
855|    if (result == 0) {
856|      answer = jv_number(mid);
857|      break;
858|    } else if (result < 0) {
859|      end = mid;
860|    } else {
861|      start = mid + 1;
862|    }
863|  }
864|  if (!jv_is_valid(answer)) {
865|    answer = jv_number(-1 - start);
866|  }
867|  jv_free(input);
868|  jv_free(target);
869|  return answer;
