1033|        if (fr == input_string+region->beg[0]) idx = len, len=0;
1034|        fr += jvp_utf8_decode_length(*fr);
1035|      }
1036|
1037|      jv match = jv_object_set(jv_object(), jv_string("offset"), jv_number(idx));
1038|
1039|      unsigned long blen = region->end[0]-region->beg[0];
1040|      match = jv_object_set(match, jv_string("length"), jv_number(len));
1041|      match = jv_object_set(match, jv_string("string"), jv_string_sized(input_string+region->beg[0],blen));
