1116|    return type_error2(values, keys, "have wrong length");
1117|
1118|  if (jv_array_length(jv_copy(values)) == 0) {
1119|    jv_free(values);
1120|    jv_free(keys);
1121|    return jv_null();
1122|  }
1123|  jv ret = jv_array_get(jv_copy(values), 0);
1124|  jv retkey = jv_array_get(jv_copy(keys), 0);
1125|  for (int i=1; i<jv_array_length(jv_copy(values)); i++) {
1126|    jv item = jv_array_get(jv_copy(keys), i);
1127|    int cmp = jv_cmp(jv_copy(item), jv_copy(retkey));
1128|    if ((cmp < 0) == (is_min == 1)) {
1129|      jv_free(retkey);
1130|      retkey = item;
1131|      jv_free(ret);
1132|      ret = jv_array_get(jv_copy(values), i);
1133|    } else {
1134|      jv_free(item);
1135|    }
1136|  }
1137|  jv_free(values);
1138|  jv_free(keys);
1139|  jv_free(retkey);
1140|  return ret;
