1281|enum trim_op {
1282|  TRIM_LEFT  = 1 << 0,
1283|  TRIM_RIGHT = 1 << 1
1284|};
1285|
1286|static jv string_trim(jv a, int op) {
1287|  if (jv_get_kind(a) != JV_KIND_STRING) {
1288|    return ret_error(a, jv_string("trim input must be a string"));
1289|  }
1290|
1291|  int len = jv_string_length_bytes(jv_copy(a));
1292|  const char *start = jv_string_value(a);
1293|  const char *trim_start = start;
1294|  const char *end = trim_start + len;
1295|  const char *trim_end = end;
1296|  int c;
1297|
1298|  if (op & TRIM_LEFT) {
1299|    for (;;) {
1300|      const char *ns = jvp_utf8_next(trim_start, end, &c);
1301|      if (!ns || !jvp_codepoint_is_whitespace(c))
1302|        break;
1303|      trim_start = ns;
1304|    }
1305|  }
1306|
1307|  // make sure not empty string or start trim has trimmed everything
1308|  if ((op & TRIM_RIGHT) && trim_end > trim_start) {
1309|    for (;;) {
1310|      const char *ns = jvp_utf8_backtrack(trim_end-1, trim_start, NULL);
1311|      jvp_utf8_next(ns, trim_end, &c);
1312|      if (!jvp_codepoint_is_whitespace(c))
1313|        break;
1314|      trim_end = ns;
1315|      if (ns == trim_start)
1316|        break;
1317|    }
1318|  }
1319|
1320|  // no new string needed if there is nothing to trim
1321|  if (trim_start == start && trim_end == end)
1322|    return a;
1323|
1324|  jv ts = jv_string_sized(trim_start, trim_end - trim_start);
1325|  jv_free(a);
1326|  return ts;
1327|}
