1468|#elif WIN32
1469|  return _mkgmtime(tm);
1470|#else
1471|  char *tz;
1472|
1473|  tz = (tz = getenv("TZ")) != NULL ? strdup(tz) : NULL;
1474|  if (tz != NULL)
1475|    setenv("TZ", "", 1);
1476|  time_t t = mktime(tm);
1477|  if (tz != NULL)
1478|    setenv("TZ", tz, 1);
1479|  return t;
