1483|/* Compute and set tm_wday */
1484|static void set_tm_wday(struct tm *tm) {
1485|  /*
1486|   * https://en.wikipedia.org/wiki/Determination_of_the_day_of_the_week#Gauss.27s_algorithm
1487|   * https://cs.uwaterloo.ca/~alopez-o/math-faq/node73.html
1488|   *
1489|   * Tested with dates from 1900-01-01 through 2100-01-01.  This
1490|   * algorithm produces the wrong day-of-the-week number for dates in
1491|   * the range 1900-01-01..1900-02-28, and for 2100-01-01..2100-02-28.
1492|   * Since this is only needed on OS X and *BSD, we might just document
1493|   * this.
1494|   */
1495|  int century = (1900 + tm->tm_year) / 100;
1496|  int year = (1900 + tm->tm_year) % 100;
1497|  if (tm->tm_mon < 2)
1498|    year--;
1499|  /*
1500|   * The month value in the wday computation below is shifted so that
1501|   * March is 1, April is 2, .., January is 11, and February is 12.
1502|   */
1503|  int mon = tm->tm_mon - 1;
1504|  if (mon < 1)
1505|    mon += 12;
1506|  int wday =
1507|    (tm->tm_mday + (int)floor((2.6 * mon - 0.2)) + year + (int)floor(year / 4.0) + (int)floor(century / 4.0) - 2 * century) % 7;
1508|  if (wday < 0)
1509|    wday += 7;
1510|#if 0
1511|  /* See commentary above */
1512|  assert(wday == tm->tm_wday || tm->tm_wday == 8);
1513|#endif
1514|  tm->tm_wday = wday;
1515|}
1516|/*
1517| * Compute and set tm_yday.
1518| *
1519| */
1520|static void set_tm_yday(struct tm *tm) {
1521|  static const int d[] = {0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334};
1522|  int mon = tm->tm_mon;
1523|  int year = 1900 + tm->tm_year;
1524|  int leap_day = 0;
1525|  if (tm->tm_mon > 1 &&
1526|      ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)))
1527|    leap_day = 1;
1528|
1529|  /* Bound check index into d[] */
1530|  if (mon < 0)
1531|    mon = -mon;
1532|  if (mon > 11)
1533|    mon %= 12;
1534|
1535|  int yday = d[mon] + leap_day + tm->tm_mday - 1;
1536|  assert(yday == tm->tm_yday || tm->tm_yday == 367);
1537|  tm->tm_yday = yday;
1538|}
