1540|static jv f_strptime(jq_state *jq, jv a, jv b) {
1541|  if (jv_get_kind(a) != JV_KIND_STRING || jv_get_kind(b) != JV_KIND_STRING) {
1542|    return ret_error2(a, b, jv_string("strptime/1 requires string inputs and arguments"));
1543|  }
1544|
1545|  struct tm tm;
1546|  memset(&tm, 0, sizeof(tm));
1547|  tm.tm_wday = 8; // sentinel
1548|  tm.tm_yday = 367; // sentinel
1549|  const char *input = jv_string_value(a);
1550|  const char *fmt = jv_string_value(b);
1551|
1552|#ifndef HAVE_STRPTIME
1553|  if (strcmp(fmt, "%Y-%m-%dT%H:%M:%SZ")) {
1554|    return ret_error2(a, b, jv_string("strptime/1 only supports ISO 8601 on this platform"));
1555|  }
1556|#endif
1557|  const char *end = strptime(input, fmt, &tm);
1558|  if (end == NULL || (*end != '\0' && !isspace((unsigned char)*end))) {
1559|    return ret_error2(a, b, jv_string_fmt("date \"%s\" does not match format \"%s\"", input, fmt));
1560|  }
1561|  jv_free(b);
1562|  /*
1563|   * This is OS X or some *BSD whose strptime() is just not that
1564|   * helpful!
1565|   *
1566|   * We don't know that the format string did involve parsing a
1567|   * year, or a month (if tm->tm_mon == 0).  But with our invalid
1568|   * day-of-week and day-of-year sentinel checks above, the worst
1569|   * this can do is produce garbage.
1570|   */
1571|#ifdef __APPLE__
1572|  /*
1573|   * Apple has made it worse, and different versions of the OS have different
1574|   * behaviors. Some versions just don't touch the fields, but others do, and
1575|   * sometimes provide wrong answers, at that! We can't tell at compile-time
1576|   * which behavior the target system will have, so instead we always use our
1577|   * functions to set these on OS X, and document that %u and %j are
1578|   * unsupported on OS X.
1579|   */
1580|  set_tm_wday(&tm);
1581|  set_tm_yday(&tm);
1582|#elif defined(WIN32) || !defined(HAVE_STRPTIME)
1583|  set_tm_wday(&tm);
1584|#else
1585|  if (tm.tm_wday == 8 && tm.tm_mday != 0 && tm.tm_mon >= 0 && tm.tm_mon <= 11)
1586|    set_tm_wday(&tm);
1587|  if (tm.tm_yday == 367 && tm.tm_mday != 0 && tm.tm_mon >= 0 && tm.tm_mon <= 11)
1588|    set_tm_yday(&tm);
1589|#endif
1590|  jv r = tm2jv(&tm);
1591|  if (*end != '\0')
1592|    r = jv_array_append(r, jv_string(end));
1593|  jv_free(a); // must come after `*end` because `end` is a pointer into `a`'s string
1594|  return r;
