156|static pfunc parse_token(struct jv_parser* p, char ch) {
157|  switch (ch) {
158|  case '[':
159|    if (p->stackpos >= MAX_PARSING_DEPTH) return "Exceeds depth limit for parsing";
160|    if (jv_is_valid(p->next)) return "Expected separator between values";
161|    push(p, jv_array());
162|    break;
163|
164|  case '{':
165|    if (p->stackpos >= MAX_PARSING_DEPTH) return "Exceeds depth limit for parsing";
166|    if (jv_is_valid(p->next)) return "Expected separator between values";
167|    push(p, jv_object());
168|    break;
169|
170|  case ':':
171|    if (!jv_is_valid(p->next))
172|      return "Expected string key before ':'";
173|    if (p->stackpos == 0 || jv_get_kind(p->stack[p->stackpos-1]) != JV_KIND_OBJECT)
174|      return "':' not as part of an object";
175|    if (jv_get_kind(p->next) != JV_KIND_STRING)
176|      return "Object keys must be strings";
177|    push(p, p->next);
178|    p->next = jv_invalid();
179|    break;
180|
181|  case ',':
182|    if (!jv_is_valid(p->next))
183|      return "Expected value before ','";
184|    if (p->stackpos == 0)
185|      return "',' not as part of an object or array";
186|    if (jv_get_kind(p->stack[p->stackpos-1]) == JV_KIND_ARRAY) {
187|      p->stack[p->stackpos-1] = jv_array_append(p->stack[p->stackpos-1], p->next);
188|      p->next = jv_invalid();
189|    } else if (jv_get_kind(p->stack[p->stackpos-1]) == JV_KIND_STRING) {
190|      assert(p->stackpos > 1 && jv_get_kind(p->stack[p->stackpos-2]) == JV_KIND_OBJECT);
191|      p->stack[p->stackpos-2] = jv_object_set(p->stack[p->stackpos-2],
192|                                              p->stack[p->stackpos-1], p->next);
193|      p->stackpos--;
194|      p->next = jv_invalid();
195|    } else {
196|      // this case hits on input like {"a", "b"}
197|      return "Objects must consist of key:value pairs";
198|    }
199|    break;
200|
201|  case ']':
202|    if (p->stackpos == 0 || jv_get_kind(p->stack[p->stackpos-1]) != JV_KIND_ARRAY)
203|      return "Unmatched ']'";
204|    if (jv_is_valid(p->next)) {
205|      p->stack[p->stackpos-1] = jv_array_append(p->stack[p->stackpos-1], p->next);
206|      p->next = jv_invalid();
207|    } else {
208|      if (jv_array_length(jv_copy(p->stack[p->stackpos-1])) != 0) {
209|        // this case hits on input like [1,2,3,]
210|        return "Expected another array element";
211|      }
212|    }
213|    jv_free(p->next);
214|    p->next = p->stack[--p->stackpos];
215|    break;
216|
217|  case '}':
218|    if (p->stackpos == 0)
219|      return "Unmatched '}'";
220|    if (jv_is_valid(p->next)) {
221|      if (jv_get_kind(p->stack[p->stackpos-1]) != JV_KIND_STRING)
222|        return "Objects must consist of key:value pairs";
223|      assert(p->stackpos > 1 && jv_get_kind(p->stack[p->stackpos-2]) == JV_KIND_OBJECT);
224|      p->stack[p->stackpos-2] = jv_object_set(p->stack[p->stackpos-2],
225|                                              p->stack[p->stackpos-1], p->next);
226|      p->stackpos--;
227|      p->next = jv_invalid();
228|    } else {
229|      if (jv_get_kind(p->stack[p->stackpos-1]) != JV_KIND_OBJECT)
230|        return "Unmatched '}'";
231|      if (jv_object_length(jv_copy(p->stack[p->stackpos-1])) != 0)
232|        return "Expected another key-value pair";
233|    }
234|    jv_free(p->next);
235|    p->next = p->stack[--p->stackpos];
236|    break;
237|  }
238|  return 0;
239|}
