250|      // Looks like {["foo"]}
251|      return "Expected string key after '{', not '['";
252|    if (p->last_seen == JV_LAST_COMMA) {
253|      last = jv_array_get(jv_copy(p->path), p->stacklen - 1);
254|      k = jv_get_kind(last);
255|      jv_free(last);
256|      if (k != JV_KIND_NUMBER)
257|        // Looks like {"x":"y",["foo"]}
258|        return "Expected string key after ',' in object, not '['";
259|    }
260|    p->path = jv_array_append(p->path, jv_number(0)); // push
261|    p->last_seen = JV_LAST_OPEN_ARRAY;
262|    p->stacklen++;
263|    break;
264|
265|  case '{':
266|    if (p->last_seen == JV_LAST_VALUE)
267|      return "Expected a separator between values";
268|    if (p->last_seen == JV_LAST_OPEN_OBJECT)
269|      // Looks like {{"foo":"bar"}}
270|      return "Expected string key after '{', not '{'";
271|    if (p->last_seen == JV_LAST_COMMA) {
272|      last = jv_array_get(jv_copy(p->path), p->stacklen - 1);
273|      k = jv_get_kind(last);
274|      jv_free(last);
275|      if (k != JV_KIND_NUMBER)
276|        // Looks like {"x":"y",{"foo":"bar"}}
277|        return "Expected string key after ',' in object, not '{'";
278|    }
279|    // Push object key: null, since we don't know it yet
280|    p->path = jv_array_append(p->path, jv_null()); // push
281|    p->last_seen = JV_LAST_OPEN_OBJECT;
282|    p->stacklen++;
283|    break;
284|
285|  case ':':
286|    last = jv_invalid();
287|    if (p->stacklen == 0 || jv_get_kind(last = jv_array_get(jv_copy(p->path), p->stacklen - 1)) == JV_KIND_NUMBER) {
288|      jv_free(last);
289|      return "':' not as part of an object";
290|    }
291|    jv_free(last);
292|    if (!jv_is_valid(p->next) || p->last_seen == JV_LAST_NONE)
293|      return "Expected string key before ':'";
294|    if (jv_get_kind(p->next) != JV_KIND_STRING)
295|      return "Object keys must be strings";
296|    if (p->last_seen != JV_LAST_VALUE)
297|      return "':' should follow a key";
298|    p->last_seen = JV_LAST_COLON;
299|    p->path = jv_array_set(p->path, p->stacklen - 1, p->next);
300|    p->next = jv_invalid();
301|    break;
302|
303|  case ',':
304|    if (p->last_seen != JV_LAST_VALUE)
305|      return "Expected value before ','";
306|    if (p->stacklen == 0)
307|      return "',' not as part of an object or array";
308|    last = jv_array_get(jv_copy(p->path), p->stacklen - 1);
309|    k = jv_get_kind(last);
310|    if (k == JV_KIND_NUMBER) {
311|      int idx = jv_number_value(last);
312|
313|      if (jv_is_valid(p->next)) {
314|        p->output = JV_ARRAY(jv_copy(p->path), p->next);
315|        p->next = jv_invalid();
316|      }
317|      p->path = jv_array_set(p->path, p->stacklen - 1, jv_number(idx + 1));
318|      p->last_seen = JV_LAST_COMMA;
319|    } else if (k == JV_KIND_STRING) {
320|      if (jv_is_valid(p->next)) {
321|        p->output = JV_ARRAY(jv_copy(p->path), p->next);
322|        p->next = jv_invalid();
323|      }
324|      p->path = jv_array_set(p->path, p->stacklen - 1, jv_null()); // ready for another key:value pair
325|      p->last_seen = JV_LAST_COMMA;
326|    } else {
327|      assert(k == JV_KIND_NULL);
328|      // this case hits on input like {,}
329|      // make sure to handle input like {"a", "b"} and {"a":, ...}
330|      jv_free(last);
331|      return "Objects must consist of key:value pairs";
332|    }
333|    jv_free(last);
334|    break;
335|
336|  case ']':
337|    if (p->stacklen == 0)
338|      return "Unmatched ']' at the top-level";
339|    if (p->last_seen == JV_LAST_COMMA)
340|      return "Expected another array element";
341|    if (p->last_seen == JV_LAST_OPEN_ARRAY)
342|      assert(!jv_is_valid(p->next));
343|
344|    last = jv_array_get(jv_copy(p->path), p->stacklen - 1);
345|    k = jv_get_kind(last);
346|    jv_free(last);
347|
348|    if (k != JV_KIND_NUMBER)
349|      return "Unmatched ']' in the middle of an object";
350|    if (jv_is_valid(p->next)) {
351|      p->output = JV_ARRAY(jv_copy(p->path), p->next, jv_true());
352|      p->next = jv_invalid();
353|    } else if (p->last_seen != JV_LAST_OPEN_ARRAY) {
354|      p->output = JV_ARRAY(jv_copy(p->path));
355|    }
356|
357|    p->path = jv_array_slice(p->path, 0, --(p->stacklen)); // pop
358|    //assert(!jv_is_valid(p->next));
359|    jv_free(p->next);
360|    p->next = jv_invalid();
361|
362|    if (p->last_seen == JV_LAST_OPEN_ARRAY)
363|      p->output = JV_ARRAY(jv_copy(p->path), jv_array()); // Empty arrays are leaves
364|
365|    if (p->stacklen == 0)
366|      p->last_seen = JV_LAST_NONE;
367|    else
368|      p->last_seen = JV_LAST_VALUE;
369|    break;
370|
371|  case '}':
372|    if (p->stacklen == 0)
373|      return "Unmatched '}' at the top-level";
374|    if (p->last_seen == JV_LAST_COMMA)
375|      return "Expected another key:value pair";
376|    if (p->last_seen == JV_LAST_OPEN_OBJECT)
377|      assert(!jv_is_valid(p->next));
378|
379|    last = jv_array_get(jv_copy(p->path), p->stacklen - 1);
380|    k = jv_get_kind(last);
381|    jv_free(last);
382|    if (k == JV_KIND_NUMBER)
383|      return "Unmatched '}' in the middle of an array";
384|
385|    if (jv_is_valid(p->next)) {
386|      if (k != JV_KIND_STRING)
387|        return "Objects must consist of key:value pairs";
388|      p->output = JV_ARRAY(jv_copy(p->path), p->next, jv_true());
389|      p->next = jv_invalid();
390|    } else {
391|      // Perhaps {"a":[]}
392|      if (p->last_seen == JV_LAST_COLON)
393|        // Looks like {"a":}
394|        return "Missing value in key:value pair";
395|      if (p->last_seen == JV_LAST_COMMA)
396|        // Looks like {"a":0,}
397|        return "Expected another key-value pair";
398|      if (p->last_seen == JV_LAST_OPEN_ARRAY)
399|        return "Unmatched '}' in the middle of an array";
400|      if (p->last_seen != JV_LAST_VALUE && p->last_seen != JV_LAST_OPEN_OBJECT)
401|        return "Unmatched '}'";
402|      if (p->last_seen != JV_LAST_OPEN_OBJECT)
403|        p->output = JV_ARRAY(jv_copy(p->path));
404|    }
405|    p->path = jv_array_slice(p->path, 0, --(p->stacklen)); // pop
406|    jv_free(p->next);
407|    p->next = jv_invalid();
408|
409|    if (p->last_seen == JV_LAST_OPEN_OBJECT)
410|      p->output = JV_ARRAY(jv_copy(p->path), jv_object()); // Empty arrays are leaves
411|
412|    if (p->stacklen == 0)
413|      p->last_seen = JV_LAST_NONE;
414|    else
415|      p->last_seen = JV_LAST_VALUE;
416|    break;
417|  }
418|  return 0;
