421|static void tokenadd(struct jv_parser* p, char c) {
422|  assert(p->tokenpos <= p->tokenlen);
423|  if (p->tokenpos >= (p->tokenlen - 1)) {
424|    p->tokenlen = p->tokenlen*2 + 256;
425|    p->tokenbuf = jv_mem_realloc(p->tokenbuf, p->tokenlen);
426|  }
427|  assert(p->tokenpos < p->tokenlen);
428|  p->tokenbuf[p->tokenpos++] = c;
