446|static pfunc found_string(struct jv_parser* p) {
447|  char* in = p->tokenbuf;
448|  char* out = p->tokenbuf;
449|  char* end = p->tokenbuf + p->tokenpos;
450|
451|  while (in < end) {
452|    char c = *in++;
453|    if (c == '\\') {
454|      if (in >= end)
455|        return "Expected escape character at end of string";
456|      c = *in++;
457|      switch (c) {
458|      case '\\':
459|      case '"':
460|      case '/': *out++ = c;    break;
461|      case 'b': *out++ = '\b'; break;
462|      case 'f': *out++ = '\f'; break;
463|      case 't': *out++ = '\t'; break;
464|      case 'n': *out++ = '\n'; break;
465|      case 'r': *out++ = '\r'; break;
466|
467|      case 'u':
468|        /* ahh, the complicated case */
469|        if (in + 4 > end)
470|          return "Invalid \\uXXXX escape";
471|        int hexvalue = unhex4(in);
472|        if (hexvalue < 0)
473|          return "Invalid characters in \\uXXXX escape";
474|        unsigned long codepoint = (unsigned long)hexvalue;
475|        in += 4;
476|        if (0xD800 <= codepoint && codepoint <= 0xDBFF) {
477|          /* who thought UTF-16 surrogate pairs were a good idea? */
478|          if (in + 6 > end || in[0] != '\\' || in[1] != 'u')
479|            return "Invalid \\uXXXX\\uXXXX surrogate pair escape";
480|          unsigned long surrogate = unhex4(in+2);
481|          if (!(0xDC00 <= surrogate && surrogate <= 0xDFFF))
482|            return "Invalid \\uXXXX\\uXXXX surrogate pair escape";
483|          in += 6;
484|          codepoint = 0x10000 + (((codepoint - 0xD800) << 10)
485|                                 |(surrogate - 0xDC00));
486|        }
487|        if (codepoint > 0x10FFFF)
488|          codepoint = 0xFFFD; // U+FFFD REPLACEMENT CHARACTER
489|        out += jvp_utf8_encode(codepoint, out);
490|        break;
491|
492|      default:
493|        return "Invalid escape";
494|      }
495|    } else {
496|      if (c >= 0 && c <= 0x001f)
497|        return "Invalid string: control characters from U+0000 through U+001F must be escaped";
498|      *out++ = c;
499|    }
500|  }
501|  TRY(value(p, jv_string_sized(p->tokenbuf, out - p->tokenbuf)));
502|  p->tokenpos = 0;
503|  return 0;
504|}
