506|static pfunc check_literal(struct jv_parser* p) {
507|  if (p->tokenpos == 0) return 0;
508|
509|  const char* pattern = 0;
510|  int plen;
511|  jv v;
512|  switch (p->tokenbuf[0]) {
513|  case 't': pattern = "true"; plen = 4; v = jv_true(); break;
514|  case 'f': pattern = "false"; plen = 5; v = jv_false(); break;
515|  case '\'':
516|    return "Invalid string literal; expected \", but got '";
517|  case 'n':
518|    // if it starts with 'n', it could be a literal "nan"
519|    if (p->tokenbuf[1] == 'u') {
520|      pattern = "null"; plen = 4; v = jv_null();
521|    }
522|  }
523|  if (pattern) {
524|    if (p->tokenpos != plen) return "Invalid literal";
525|    for (int i=0; i<plen; i++)
526|      if (p->tokenbuf[i] != pattern[i])
527|        return "Invalid literal";
528|    TRY(value(p, v));
529|  } else {
530|    // FIXME: better parser
531|    p->tokenbuf[p->tokenpos] = 0;
532|#ifdef USE_DECNUM
533|    jv number = jv_number_with_literal(p->tokenbuf);
534|    if (jv_get_kind(number) == JV_KIND_INVALID) {
535|      return "Invalid numeric literal";
536|    }
537|    TRY(value(p, number));
538|#else
539|    char *end = 0;
540|    double d = jvp_strtod(&p->dtoa, p->tokenbuf, &end);
541|    if (end == 0 || *end != 0) {
542|      return "Invalid numeric literal";
543|    }
544|    TRY(value(p, jv_number(d)));
545|#endif
546|  }
547|  p->tokenpos = 0;
548|  return 0;
