551|typedef enum {
552|  LITERAL,
553|  WHITESPACE,
554|  STRUCTURE,
555|  QUOTE,
556|  INVALID
557|} chclass;
558|
559|static chclass classify(char c) {
560|  switch (c) {
561|  case ' ':
562|  case '\t':
563|  case '\r':
564|  case '\n':
565|    return WHITESPACE;
566|  case '"':
567|    return QUOTE;
568|  case '[':
569|  case ',':
570|  case ']':
571|  case '{':
572|  case ':':
573|  case '}':
574|    return STRUCTURE;
575|  default:
576|    return LITERAL;
577|  }
578|}
