581|static const presult OK = "output produced";
582|
583|static int parse_check_done(struct jv_parser* p, jv* out) {
584|  if (p->stackpos == 0 && jv_is_valid(p->next)) {
585|    *out = p->next;
586|    p->next = jv_invalid();
587|    return 1;
588|  } else {
589|    return 0;
590|  }
591|}
592|
593|static int stream_check_done(struct jv_parser* p, jv* out) {
594|  if (p->stacklen == 0 && jv_is_valid(p->next)) {
595|    *out = JV_ARRAY(jv_copy(p->path),p->next);
596|    p->next = jv_invalid();
597|    return 1;
598|  } else if (jv_is_valid(p->output)) {
599|    if (jv_array_length(jv_copy(p->output)) > 2) {
600|      // At end of an array or object, necessitating one more output by
601|      // which to indicate this
602|      *out = jv_array_slice(jv_copy(p->output), 0, 2);
603|      p->output = jv_array_slice(p->output, 0, 1);      // arrange one more output
604|    } else {
605|      // No further processing needed
606|      *out = p->output;
607|      p->output = jv_invalid();
608|    }
609|    return 1;
610|  } else {
611|    return 0;
612|  }
613|}
