615|static int seq_check_truncation(struct jv_parser* p) {
616|  return (!p->last_ch_was_ws && (p->stackpos > 0 || p->tokenpos > 0 || jv_get_kind(p->next) == JV_KIND_NUMBER));
617|}
618|
619|static int stream_seq_check_truncation(struct jv_parser* p) {
620|  jv_kind k = jv_get_kind(p->next);
621|  return (p->stacklen > 0 || k == JV_KIND_NUMBER || k == JV_KIND_TRUE || k == JV_KIND_FALSE || k == JV_KIND_NULL);
622|}
