624|static int parse_is_top_num(struct jv_parser* p) {
625|  return (p->stackpos == 0 && jv_get_kind(p->next) == JV_KIND_NUMBER);
626|}
627|
628|static int stream_is_top_num(struct jv_parser* p) {
629|  return (p->stacklen == 0 && jv_get_kind(p->next) == JV_KIND_NUMBER);
630|}
631|
632|#define check_done(p, o) \
633|   (((p)->flags & JV_PARSE_STREAMING) ? stream_check_done((p), (o)) : parse_check_done((p), (o)))
634|
635|#define token(p, ch) \
636|   (((p)->flags & JV_PARSE_STREAMING) ? stream_token((p), (ch)) : parse_token((p), (ch)))
637|
638|#define check_truncation(p) \
639|   (((p)->flags & JV_PARSE_STREAMING) ? stream_seq_check_truncation((p)) : seq_check_truncation((p)))
640|
641|#define is_top_num(p) \
642|   (((p)->flags & JV_PARSE_STREAMING) ? stream_is_top_num((p)) : parse_is_top_num((p)))
643|
644|static pfunc scan(struct jv_parser* p, char ch, jv* out) {
645|  p->column++;
646|  if (ch == '\n') {
647|    p->line++;
648|    p->column = 0;
649|  }
650|  if ((p->flags & JV_PARSE_SEQ)
651|      && ch == '\036' /* ASCII RS; see draft-ietf-json-sequence-07 */) {
652|    if (check_truncation(p)) {
653|      if (check_literal(p) == 0 && is_top_num(p))
654|        return "Potentially truncated top-level numeric value";
655|      return "Truncated value";
656|    }
657|    TRY(check_literal(p));
658|    if (p->st == JV_PARSER_NORMAL && check_done(p, out))
659|      return OK;
660|    // shouldn't happen?
661|    assert(!jv_is_valid(*out));
662|    parser_reset(p);
663|    jv_free(*out);
664|    *out = jv_invalid();
665|    return OK;
666|  }
667|  presult answer = 0;
668|  p->last_ch_was_ws = 0;
669|  if (p->st == JV_PARSER_NORMAL) {
670|    chclass cls = classify(ch);
671|    if (cls == WHITESPACE)
672|      p->last_ch_was_ws = 1;
673|    if (cls != LITERAL) {
674|      TRY(check_literal(p));
675|      if (check_done(p, out)) answer = OK;
676|    }
677|    switch (cls) {
678|    case LITERAL:
679|      tokenadd(p, ch);
680|      break;
681|    case WHITESPACE:
682|      break;
683|    case QUOTE:
684|      p->st = JV_PARSER_STRING;
685|      break;
686|    case STRUCTURE:
687|      TRY(token(p, ch));
688|      break;
689|    case INVALID:
690|      return "Invalid character";
691|    }
692|    if (check_done(p, out)) answer = OK;
693|  } else {
694|    if (ch == '"' && p->st == JV_PARSER_STRING) {
695|      TRY(found_string(p));
696|      p->st = JV_PARSER_NORMAL;
697|      if (check_done(p, out)) answer = OK;
698|    } else {
699|      tokenadd(p, ch);
700|      if (ch == '\\' && p->st == JV_PARSER_STRING) {
701|        p->st = JV_PARSER_STRING_ESCAPE;
702|      } else {
703|        p->st = JV_PARSER_STRING;
704|      }
705|    }
706|  }
707|  return answer;
708|}
