730|void jv_parser_set_buf(struct jv_parser* p, const char* buf, int length, int is_partial) {
731|  assert((p->curr_buf == 0 || p->curr_buf_pos == p->curr_buf_length)
732|         && "previous buffer not exhausted");
733|  while (length > 0 && p->bom_strip_position < sizeof(UTF8_BOM)) {
734|    if ((unsigned char)*buf == UTF8_BOM[p->bom_strip_position]) {
735|      // matched a BOM character
736|      buf++;
737|      length--;
738|      p->bom_strip_position++;
739|    } else {
740|      if (p->bom_strip_position == 0) {
741|        // no BOM in this document
742|        p->bom_strip_position = sizeof(UTF8_BOM);
743|      } else {
744|        // malformed BOM (prefix present, rest missing)
745|        p->bom_strip_position = 0xff;
746|      }
747|    }
748|  }
749|  p->curr_buf = buf;
750|  p->curr_buf_length = length;
751|  p->curr_buf_pos = 0;
752|  p->curr_buf_is_partial = is_partial;
