755|static jv make_error(struct jv_parser*, const char *, ...) JV_PRINTF_LIKE(2, 3);
756|
757|static jv make_error(struct jv_parser* p, const char *fmt, ...) {
758|  va_list ap;
759|  va_start(ap, fmt);
760|  jv e = jv_string_vfmt(fmt, ap);
761|  va_end(ap);
762|  if ((p->flags & JV_PARSE_STREAM_ERRORS))
763|    return JV_ARRAY(e, jv_copy(p->path));
764|  return jv_invalid_with_msg(e);
765|}
766|
767|jv jv_parser_next(struct jv_parser* p) {
768|  if (p->eof)
769|    return jv_invalid();
770|  if (!p->curr_buf)
771|    return jv_invalid(); // Need a buffer
772|  if (p->bom_strip_position == 0xff) {
773|    if (!(p->flags & JV_PARSE_SEQ))
774|      return jv_invalid_with_msg(jv_string("Malformed BOM"));
775|    p->st =JV_PARSER_WAITING_FOR_RS;
776|    parser_reset(p);
777|  }
778|  jv value = jv_invalid();
779|  if ((p->flags & JV_PARSE_STREAMING) && stream_check_done(p, &value))
780|    return value;
781|  char ch;
782|  presult msg = 0;
783|  while (!msg && p->curr_buf_pos < p->curr_buf_length) {
784|    ch = p->curr_buf[p->curr_buf_pos++];
785|    if (p->st == JV_PARSER_WAITING_FOR_RS) {
786|      if (ch == '\n') {
787|        p->line++;
788|        p->column = 0;
789|      } else {
790|        p->column++;
791|      }
792|      if (ch == '\036')
793|        p->st = JV_PARSER_NORMAL;
794|      continue; // need to resync, wait for RS
795|    }
796|    msg = scan(p, ch, &value);
797|  }
798|  if (msg == OK) {
799|    return value;
800|  } else if (msg) {
801|    jv_free(value);
802|    if (ch != '\036' && (p->flags & JV_PARSE_SEQ)) {
803|      // Skip to the next RS
804|      p->st = JV_PARSER_WAITING_FOR_RS;
805|      value = make_error(p, "%s at line %d, column %d (need RS to resync)", msg, p->line, p->column);
806|      parser_reset(p);
807|      return value;
808|    }
809|    value = make_error(p, "%s at line %d, column %d", msg, p->line, p->column);
810|    parser_reset(p);
811|    if (!(p->flags & JV_PARSE_SEQ)) {
812|      // We're not parsing a JSON text sequence; throw this buffer away.
813|      // XXX We should fail permanently here.
814|      p->curr_buf = 0;
815|      p->curr_buf_pos = 0;
816|    } // Else ch must be RS; don't clear buf so we can start parsing again after this ch
817|    return value;
818|  } else if (p->curr_buf_is_partial) {
819|    assert(p->curr_buf_pos == p->curr_buf_length);
820|    // need another buffer
821|    return jv_invalid();
822|  } else {
823|    // at EOF
824|    p->eof = 1;
825|    assert(p->curr_buf_pos == p->curr_buf_length);
826|    jv_free(value);
827|    if (p->st == JV_PARSER_WAITING_FOR_RS)
828|      return make_error(p, "Unfinished abandoned text at EOF at line %d, column %d", p->line, p->column);
829|    if (p->st != JV_PARSER_NORMAL) {
830|      value = make_error(p, "Unfinished string at EOF at line %d, column %d", p->line, p->column);
831|      parser_reset(p);
832|      p->st = JV_PARSER_WAITING_FOR_RS;
833|      return value;
834|    }
835|    if ((msg = check_literal(p))) {
836|      value = make_error(p, "%s at EOF at line %d, column %d", msg, p->line, p->column);
837|      parser_reset(p);
838|      p->st = JV_PARSER_WAITING_FOR_RS;
839|      return value;
840|    }
841|    if (((p->flags & JV_PARSE_STREAMING) && p->stacklen != 0) ||
842|        (!(p->flags & JV_PARSE_STREAMING) && p->stackpos != 0)) {
843|      value = make_error(p, "Unfinished JSON term at EOF at line %d, column %d", p->line, p->column);
844|      parser_reset(p);
845|      p->st = JV_PARSER_WAITING_FOR_RS;
846|      return value;
847|    }
848|    // p->next is either invalid (nothing here, but no syntax error)
849|    // or valid (this is the value). either way it's the thing to return
850|    if ((p->flags & JV_PARSE_STREAMING) && jv_is_valid(p->next)) {
851|      value = JV_ARRAY(jv_copy(p->path), p->next); // except in streaming mode we've got to make it [path,value]
852|    } else {
853|      value = p->next;
854|    }
855|    p->next = jv_invalid();
856|    if ((p->flags & JV_PARSE_SEQ) && !p->last_ch_was_ws && jv_get_kind(value) == JV_KIND_NUMBER) {
857|      jv_free(value);
858|      return make_error(p, "Potentially truncated top-level numeric value at EOF at line %d, column %d", p->line, p->column);
859|    }
860|    return value;
861|  }
862|}
863|
864|jv jv_parse_sized_custom_flags(const char* string, int length, int flags) {
865|  struct jv_parser parser;
866|  parser_init(&parser, flags);
867|  jv_parser_set_buf(&parser, string, length, 0);
868|  jv value = jv_parser_next(&parser);
869|  if (jv_is_valid(value)) {
870|    jv next = jv_parser_next(&parser);
871|    if (jv_is_valid(next)) {
872|      // multiple JSON values, we only wanted one
873|      jv_free(value);
874|      jv_free(next);
875|      value = jv_invalid_with_msg(jv_string("Unexpected extra JSON values"));
876|    } else if (jv_invalid_has_msg(jv_copy(next))) {
877|      // parser error after the first JSON value
878|      jv_free(value);
879|      value = next;
880|    } else {
881|      // a single valid JSON value
882|      jv_free(next);
883|    }
884|  } else if (jv_invalid_has_msg(jv_copy(value))) {
885|    // parse error, we'll return it
886|  } else {
887|    // no value at all
888|    jv_free(value);
889|    value = jv_invalid_with_msg(jv_string("Expected JSON value"));
890|  }
891|  parser_free(&parser);
892|
893|  if (!jv_is_valid(value) && jv_invalid_has_msg(jv_copy(value))) {
894|    jv msg = jv_invalid_get_msg(value);
895|    value = jv_invalid_with_msg(jv_string_fmt("%s (while parsing '%s')",
896|                                              jv_string_value(msg),
897|                                              string));
898|    jv_free(msg);
899|  }
900|  return value;
901|}
902|
903|jv jv_parse_sized(const char* string, int length) {
904|  return jv_parse_sized_custom_flags(string, length, 0);
905|}
