222|#ifndef __MINGW32__
223|/* Copied from Heimdal: thread-specific keys; see lib/base/dll.c in Heimdal */
224|
225|/*
226| * This is an implementation of thread-specific storage with
227| * destructors.  WIN32 doesn't quite have this.  Instead it has
228| * DllMain(), an entry point in every DLL that gets called to notify the
229| * DLL of thread/process "attach"/"detach" events.
230| *
231| * We use __thread (or __declspec(thread)) for the thread-local itself
232| * and DllMain() DLL_THREAD_DETACH events to drive destruction of
233| * thread-local values.
234| *
235| * When building in maintainer mode on non-Windows pthread systems this
236| * uses a single pthread key instead to implement multiple keys.  This
237| * keeps the code from rotting when modified by non-Windows developers.
238| */
239|
240|/* Logical array of keys that grows lock-lessly */
241|typedef struct tls_keys tls_keys;
242|struct tls_keys {
243|    void (**keys_dtors)(void *);    /* array of destructors         */
244|    size_t keys_start_idx;          /* index of first destructor    */
245|    size_t keys_num;
246|    tls_keys *keys_next;
247|};
248|
249|/*
250| * Well, not quite locklessly.  We need synchronization primitives to do
251| * this locklessly.  An atomic CAS will do.
252| */
253|static pthread_mutex_t tls_key_defs_lock = PTHREAD_MUTEX_INITIALIZER;
254|static tls_keys *tls_key_defs;
255|
256|/* Logical array of values (per-thread; no locking needed here) */
257|struct tls_values {
258|    void **values; /* realloc()ed */
259|    size_t values_num;
260|};
261|
262|#ifdef _MSC_VER
263|static __declspec(thread) struct nomem_handler nomem_handler;
264|#else
265|static __thread struct tls_values values;
266|#endif
267|
268|#define DEAD_KEY ((void *)8)
269|
270|static void
271|w32_service_thread_detach(void *unused)
272|{
273|    tls_keys *key_defs;
274|    void (*dtor)(void*);
275|    size_t i;
276|
277|    pthread_mutex_lock(&tls_key_defs_lock);
278|    key_defs = tls_key_defs;
279|    pthread_mutex_unlock(&tls_key_defs_lock);
280|
281|    if (key_defs == NULL)
282|        return;
283|
284|    for (i = 0; i < values.values_num; i++) {
285|        assert(i >= key_defs->keys_start_idx);
286|        if (i >= key_defs->keys_start_idx + key_defs->keys_num) {
287|            pthread_mutex_lock(&tls_key_defs_lock);
288|            key_defs = key_defs->keys_next;
289|            pthread_mutex_unlock(&tls_key_defs_lock);
290|
291|            assert(key_defs != NULL);
292|            assert(i >= key_defs->keys_start_idx);
293|            assert(i < key_defs->keys_start_idx + key_defs->keys_num);
294|        }
295|        dtor = key_defs->keys_dtors[i - key_defs->keys_start_idx];
296|        if (values.values[i] != NULL && dtor != NULL && dtor != DEAD_KEY)
297|            dtor(values.values[i]);
298|        values.values[i] = NULL;
299|    }
300|}
