307|BOOL WINAPI DllMain(HINSTANCE hinstDLL,
308|                    DWORD fdwReason,
309|                    LPVOID lpvReserved)
310|{
311|    switch (fdwReason) {
312|    case DLL_PROCESS_ATTACH:
313|	/*create_pt_key();*/
314|	jv_tsd_dtoa_ctx_init();
315|	jv_tsd_dec_ctx_init();
316|	return TRUE;
317|    case DLL_PROCESS_DETACH:
318|	jv_tsd_dtoa_ctx_fini();
319|	jv_tsd_dec_ctx_fini();
320|	return TRUE;
321|    case DLL_THREAD_ATTACH: return 0;
322|    case DLL_THREAD_DETACH:
323|        w32_service_thread_detach(NULL);
324|        return TRUE;
325|    default: return TRUE;
326|    }
