329|int
330|pthread_key_create(pthread_key_t *key, void (*dtor)(void *))
331|{
332|    tls_keys *key_defs, *new_key_defs;
333|    size_t i, k;
334|    int ret = ENOMEM;
335|
336|    pthread_mutex_lock(&tls_key_defs_lock);
337|    if (tls_key_defs == NULL) {
338|        /* First key */
339|        new_key_defs = calloc(1, sizeof(*new_key_defs));
340|        if (new_key_defs == NULL) {
341|            pthread_mutex_unlock(&tls_key_defs_lock);
342|            return ENOMEM;
343|        }
344|        new_key_defs->keys_num = 8;
345|        new_key_defs->keys_dtors = calloc(new_key_defs->keys_num,
346|                                          sizeof(*new_key_defs->keys_dtors));
347|        if (new_key_defs->keys_dtors == NULL) {
348|            pthread_mutex_unlock(&tls_key_defs_lock);
349|            free(new_key_defs);
350|            return ENOMEM;
351|        }
352|        tls_key_defs = new_key_defs;
353|        new_key_defs->keys_dtors[0] = dtor;
354|        for (i = 1; i < new_key_defs->keys_num; i++)
355|            new_key_defs->keys_dtors[i] = NULL;
356|        pthread_mutex_unlock(&tls_key_defs_lock);
357|        return 0;
358|    }
359|
360|    for (key_defs = tls_key_defs;
361|         key_defs != NULL;
362|         key_defs = key_defs->keys_next) {
363|        k = key_defs->keys_start_idx;
364|        for (i = 0; i < key_defs->keys_num; i++, k++) {
365|            if (key_defs->keys_dtors[i] == NULL) {
366|                /* Found free slot; use it */
367|                key_defs->keys_dtors[i] = dtor;
368|                *key = k;
369|                pthread_mutex_unlock(&tls_key_defs_lock);
370|                return 0;
371|            }
372|        }
373|        if (key_defs->keys_next != NULL)
374|            continue;
375|
376|        /* Grow the registration array */
377|        /* XXX DRY */
378|        new_key_defs = calloc(1, sizeof(*new_key_defs));
379|        if (new_key_defs == NULL)
380|            break;
381|
382|        new_key_defs->keys_dtors =
383|            calloc(key_defs->keys_num + key_defs->keys_num / 2,
384|                   sizeof(*new_key_defs->keys_dtors));
385|        if (new_key_defs->keys_dtors == NULL) {
386|            free(new_key_defs);
387|            break;
388|        }
389|        new_key_defs->keys_start_idx = key_defs->keys_start_idx +
390|            key_defs->keys_num;
391|        new_key_defs->keys_num = key_defs->keys_num + key_defs->keys_num / 2;
392|        new_key_defs->keys_dtors[i] = dtor;
393|        for (i = 1; i < new_key_defs->keys_num; i++)
394|            new_key_defs->keys_dtors[i] = NULL;
395|        key_defs->keys_next = new_key_defs;
396|        ret = 0;
397|        break;
398|    }
399|    pthread_mutex_unlock(&tls_key_defs_lock);
400|    return ret;
401|}
402|
403|static void
404|key_lookup(pthread_key_t key, tls_keys **kd,
405|           size_t *dtor_idx, void (**dtor)(void *))
406|{
407|    tls_keys *key_defs;
408|
409|    if (kd != NULL)
410|        *kd = NULL;
411|    if (dtor_idx != NULL)
412|        *dtor_idx = 0;
413|    if (dtor != NULL)
414|        *dtor = NULL;
415|
416|    pthread_mutex_lock(&tls_key_defs_lock);
417|    key_defs = tls_key_defs;
418|    pthread_mutex_unlock(&tls_key_defs_lock);
419|
420|    while (key_defs != NULL) {
421|        if (key >= key_defs->keys_start_idx &&
422|            key < key_defs->keys_start_idx + key_defs->keys_num) {
423|            if (kd != NULL)
424|                *kd = key_defs;
425|            if (dtor_idx != NULL)
426|                *dtor_idx = key - key_defs->keys_start_idx;
427|            if (dtor != NULL)
428|                *dtor = key_defs->keys_dtors[key - key_defs->keys_start_idx];
429|            return;
430|        }
431|
432|        pthread_mutex_lock(&tls_key_defs_lock);
433|        key_defs = key_defs->keys_next;
434|        pthread_mutex_unlock(&tls_key_defs_lock);
435|        assert(key_defs != NULL);
436|        assert(key >= key_defs->keys_start_idx);
437|    }
438|}
