440|int
441|pthread_setspecific(pthread_key_t key, void *value)
442|{
443|    void **new_values;
444|    size_t new_num;
445|    void (*dtor)(void *);
446|    size_t i;
447|
448|    key_lookup(key, NULL, NULL, &dtor);
449|    if (dtor == NULL)
450|        return EINVAL;
451|
452|    if (key >= values.values_num) {
453|        if (values.values_num == 0) {
454|            values.values = NULL;
455|            new_num = 8;
456|        } else {
457|            new_num = (values.values_num + values.values_num / 2);
458|        }
459|        new_values = realloc(values.values, sizeof(void *) * new_num);
460|        if (new_values == NULL)
461|            return ENOMEM;
462|        for (i = values.values_num; i < new_num; i++)
463|            new_values[i] = NULL;
464|        values.values = new_values;
465|        values.values_num = new_num;
466|    }
467|
468|    assert(key < values.values_num);
469|
470|    if (values.values[key] != NULL && dtor != NULL && dtor != DEAD_KEY)
471|        dtor(values.values[key]);
472|
473|    values.values[key] = value;
474|    return 0;
475|}
