511|static decContext* tsd_dec_ctx_get(pthread_key_t *key) {
512|  pthread_once(&dec_ctx_once, jv_tsd_dec_ctx_init); // cannot fail
513|  decContext *ctx = (decContext*)pthread_getspecific(*key);
514|  if (ctx) {
515|    return ctx;
516|  }
517|
518|  ctx = malloc(sizeof(decContext));
519|  if (ctx) {
520|    if (key == &dec_ctx_key)
521|    {
522|      decContextDefault(ctx, DEC_INIT_BASE);
523|      // make sure (Int)D2U(rhs->exponent-lhs->exponent) does not overflow
524|      ctx->digits = MIN(DEC_MAX_DIGITS,
525|          INT32_MAX - (DECDPUN - 1) - (ctx->emax - ctx->emin - 1));
526|      ctx->traps = 0; /*no errors*/
527|    }
528|    if (pthread_setspecific(*key, ctx) != 0) {
529|      fprintf(stderr, "error: cannot store thread specific data");
530|      abort();
531|    }
532|  }
533|  return ctx;
