580|  jvp_literal_number* n = jvp_literal_number_alloc(strlen(literal));
581|
582|  decContext *ctx = DEC_CONTEXT();
583|  decContextClearStatus(ctx, DEC_Conversion_syntax);
584|  decNumberFromString(&n->num_decimal, literal, ctx);
585|
586|  if (ctx->status & DEC_Conversion_syntax) {
587|    jv_mem_free(n);
588|    return JV_INVALID;
589|  }
