595|static double jvp_literal_number_to_double(jv j) {
596|  assert(JVP_HAS_FLAGS(j, JVP_FLAGS_NUMBER_LITERAL));
597|  decContext dblCtx;
598|
599|  // init as decimal64 but change digits to allow conversion to binary64 (double)
600|  decContextDefault(&dblCtx, DEC_INIT_DECIMAL64);
601|  dblCtx.digits = DEC_NUMBER_DOUBLE_PRECISION;
602|
603|  decNumber *p_dec_number = jvp_dec_number_ptr(j);
604|  decNumberDoublePrecision dec_double;
605|  char literal[DEC_NUMBER_DOUBLE_PRECISION + DEC_NUMBER_STRING_GUARD + 1];
606|
607|  // reduce the number to the shortest possible form
608|  // that fits into the 64 bit floating point representation
609|  decNumberReduce(&dec_double.number, p_dec_number, &dblCtx);
610|
611|  decNumberToString(&dec_double.number, literal);
612|
613|  char *end;
614|  return jvp_strtod(tsd_dtoa_context_get(), literal, &end);
