858|static jv* jvp_array_write(jv* a, int i) {
859|  assert(i >= 0);
860|  jvp_array* array = jvp_array_ptr(*a);
861|
862|  int pos = i + jvp_array_offset(*a);
863|  if (pos < array->alloc_length && jvp_refcnt_unshared(a->u.ptr)) {
864|    // use existing array space
865|    for (int j = array->length; j <= pos; j++) {
866|      array->elements[j] = JV_NULL;
867|    }
868|    array->length = imax(pos + 1, array->length);
869|    a->size = imax(i + 1, a->size);
870|    return &array->elements[pos];
871|  } else {
872|    // allocate a new array
873|    int new_length = imax(i + 1, jvp_array_length(*a));
874|    jvp_array* new_array = jvp_array_alloc(ARRAY_SIZE_ROUND_UP(new_length));
875|    int j;
876|    for (j = 0; j < jvp_array_length(*a); j++) {
877|      new_array->elements[j] =
878|        jv_copy(array->elements[j + jvp_array_offset(*a)]);
879|    }
880|    for (; j < new_length; j++) {
881|      new_array->elements[j] = JV_NULL;
882|    }
883|    new_array->length = new_length;
884|    jvp_array_free(*a);
885|    jv new_jv = {JVP_FLAGS_ARRAY, 0, 0, new_length, {&new_array->refcnt}};
886|    *a = new_jv;
887|    return &new_array->elements[i];
888|  }
