905|static void jvp_clamp_slice_params(int len, int *pstart, int *pend)
906|{
907|  if (*pstart < 0) *pstart = len + *pstart;
908|  if (*pend < 0) *pend = len + *pend;
909|
910|  if (*pstart < 0) *pstart = 0;
911|  if (*pstart > len) *pstart = len;
912|  if (*pend > len) *pend = len;
913|  if (*pend < *pstart) *pend = *pstart;
