941|static jv jvp_array_slice(jv a, int start, int end) {
942|  assert(JVP_HAS_KIND(a, JV_KIND_ARRAY));
943|  int len = jvp_array_length(a);
944|  jvp_clamp_slice_params(len, &start, &end);
945|  assert(0 <= start && start <= end && end <= len);
946|
947|  // FIXME: maybe slice should reallocate if the slice is small enough
948|  if (start == end) {
949|    jv_free(a);
950|    return jv_array();
951|  }
952|
953|  if (a.offset + start >= 1 << (sizeof(a.offset) * CHAR_BIT)) {
954|    jv r = jv_array_sized(end - start);
955|    for (int i = start; i < end; i++)
956|      r = jv_array_append(r, jv_array_get(jv_copy(a), i));
957|    jv_free(a);
958|    return r;
959|  } else {
960|    a.offset += start;
961|    a.size = end - start;
962|    return a;
963|  }
964|}
