1086|/* Copy a UTF8 string, replacing all badly encoded points with U+FFFD */
1087|static jv jvp_string_copy_replace_bad(const char* data, uint32_t length) {
1088|  const char* end = data + length;
1089|  const char* i = data;
1090|
1091|  uint32_t maxlength = length * 3 + 1; // worst case: all bad bytes, each becomes a 3-byte U+FFFD
1092|  jvp_string* s = jvp_string_alloc(maxlength);
1093|  char* out = s->data;
1094|  int c = 0;
1095|
1096|  while ((i = jvp_utf8_next(i, end, &c))) {
1097|    if (c == -1) {
1098|      c = 0xFFFD; // U+FFFD REPLACEMENT CHARACTER
1099|    }
1100|    out += jvp_utf8_encode(c, out);
1101|    assert(out < s->data + maxlength);
1102|  }
1103|  length = out - s->data;
1104|  s->data[length] = 0;
1105|  s->length_hashed = length << 1;
1106|  jv r = {JVP_FLAGS_STRING, 0, 0, 0, {&s->refcnt}};
1107|  return r;
1108|}
