1110|/* Assumes valid UTF8 */
1111|static jv jvp_string_new(const char* data, uint32_t length) {
1112|  jvp_string* s = jvp_string_alloc(length);
1113|  s->length_hashed = length << 1;
1114|  if (data != NULL)
1115|    memcpy(s->data, data, length);
1116|  s->data[length] = 0;
1117|  jv r = {JVP_FLAGS_STRING, 0, 0, 0, {&s->refcnt}};
1118|  return r;
1119|}
