1147|static jv jvp_string_append(jv string, const char* data, uint32_t len) {
1148|  jvp_string* s = jvp_string_ptr(string);
1149|  uint32_t currlen = jvp_string_length(s);
1150|
1151|  if (jvp_refcnt_unshared(string.u.ptr) &&
1152|      jvp_string_remaining_space(s) >= len) {
1153|    // the next string fits at the end of a
1154|    memcpy(s->data + currlen, data, len);
1155|    s->data[currlen + len] = 0;
1156|    s->length_hashed = (currlen + len) << 1;
1157|    return string;
1158|  } else {
1159|    // allocate a bigger buffer and copy
1160|    uint32_t allocsz = (currlen + len) * 2;
1161|    if (allocsz < 32) allocsz = 32;
1162|    jvp_string* news = jvp_string_alloc(allocsz);
1163|    news->length_hashed = (currlen + len) << 1;
1164|    memcpy(news->data, s->data, currlen);
1165|    memcpy(news->data + currlen, data, len);
1166|    news->data[currlen + len] = 0;
1167|    jvp_string_free(string);
1168|    jv r = {JVP_FLAGS_STRING, 0, 0, 0, {&news->refcnt}};
1169|    return r;
1170|  }
