1173|static const uint32_t HASH_SEED = 0x432A9843;
1174|
1175|static uint32_t rotl32 (uint32_t x, int8_t r){
1176|  return (x << r) | (x >> (32 - r));
1177|}
1178|
1179|static uint32_t jvp_string_hash(jv jstr) {
1180|  jvp_string* str = jvp_string_ptr(jstr);
1181|  if (str->length_hashed & 1)
1182|    return str->hash;
1183|
1184|  /* The following is based on MurmurHash3.
1185|     MurmurHash3 was written by Austin Appleby, and is placed
1186|     in the public domain. */
1187|
1188|  const uint8_t* data = (const uint8_t*)str->data;
1189|  int len = (int)jvp_string_length(str);
1190|  const int nblocks = len / 4;
1191|
1192|  uint32_t h1 = HASH_SEED;
1193|
1194|  const uint32_t c1 = 0xcc9e2d51;
1195|  const uint32_t c2 = 0x1b873593;
1196|  const uint32_t* blocks = (const uint32_t *)(data + nblocks*4);
1197|
1198|  for(int i = -nblocks; i; i++) {
1199|    uint32_t k1 = blocks[i]; //FIXME: endianness/alignment
1200|
1201|    k1 *= c1;
1202|    k1 = rotl32(k1,15);
1203|    k1 *= c2;
1204|
1205|    h1 ^= k1;
1206|    h1 = rotl32(h1,13);
1207|    h1 = h1*5+0xe6546b64;
1208|  }
1209|
1210|  const uint8_t* tail = (const uint8_t*)(data + nblocks*4);
1211|
1212|  uint32_t k1 = 0;
1213|
1214|  switch(len & 3) {
1215|  case 3: k1 ^= tail[2] << 16;
1216|          JQ_FALLTHROUGH;
1217|  case 2: k1 ^= tail[1] << 8;
1218|          JQ_FALLTHROUGH;
1219|  case 1: k1 ^= tail[0];
1220|          k1 *= c1; k1 = rotl32(k1,15); k1 *= c2; h1 ^= k1;
1221|  }
1222|
1223|  h1 ^= len;
1224|
1225|  h1 ^= h1 >> 16;
1226|  h1 *= 0x85ebca6b;
1227|  h1 ^= h1 >> 13;
1228|  h1 *= 0xc2b2ae35;
1229|  h1 ^= h1 >> 16;
1230|
1231|  str->length_hashed |= 1;
1232|  str->hash = h1;
1233|
1234|  return h1;
1235|}
