1284|jv jv_string_indexes(jv j, jv k) {
1285|  assert(JVP_HAS_KIND(j, JV_KIND_STRING));
1286|  assert(JVP_HAS_KIND(k, JV_KIND_STRING));
1287|  const char *jstr = jv_string_value(j);
1288|  const char *idxstr = jv_string_value(k);
1289|  const char *p, *lp;
1290|  int jlen = jv_string_length_bytes(jv_copy(j));
1291|  int idxlen = jv_string_length_bytes(jv_copy(k));
1292|  jv a = jv_array();
1293|
1294|  if (idxlen != 0) {
1295|    int n = 0;
1296|    p = lp = jstr;
1297|    while ((p = _jq_memmem(p, (jstr + jlen) - p, idxstr, idxlen)) != NULL) {
1298|      while (lp < p) {
1299|        lp += jvp_utf8_decode_length(*lp);
1300|        n++;
1301|      }
1302|
1303|      a = jv_array_append(a, jv_number(n));
1304|      p++;
1305|    }
1306|  }
1307|  jv_free(j);
1308|  jv_free(k);
1309|  return a;
