1312|jv jv_string_split(jv j, jv sep) {
1313|  assert(JVP_HAS_KIND(j, JV_KIND_STRING));
1314|  assert(JVP_HAS_KIND(sep, JV_KIND_STRING));
1315|  const char *jstr = jv_string_value(j);
1316|  const char *jend = jstr + jv_string_length_bytes(jv_copy(j));
1317|  const char *sepstr = jv_string_value(sep);
1318|  const char *p, *s;
1319|  int seplen = jv_string_length_bytes(jv_copy(sep));
1320|  jv a = jv_array();
1321|
1322|  assert(jv_get_refcnt(a) == 1);
1323|
1324|  if (seplen == 0) {
1325|    int c;
1326|    while ((jstr = jvp_utf8_next(jstr, jend, &c)))
1327|      a = jv_array_append(a, jv_string_append_codepoint(jv_string(""), c));
1328|  } else {
1329|    for (p = jstr; p < jend; p = s + seplen) {
1330|      s = _jq_memmem(p, jend - p, sepstr, seplen);
1331|      if (s == NULL)
1332|        s = jend;
1333|      a = jv_array_append(a, jv_string_sized(p, s - p));
1334|      // Add an empty string to denote that j ends on a sep
1335|      if (s + seplen == jend && seplen != 0)
1336|        a = jv_array_append(a, jv_string(""));
1337|    }
1338|  }
1339|  jv_free(j);
1340|  jv_free(sep);
1341|  return a;
