1357|jv jv_string_implode(jv j) {
1358|  assert(JVP_HAS_KIND(j, JV_KIND_ARRAY));
1359|  int len = jv_array_length(jv_copy(j));
1360|  jv s = jv_string_empty(len);
1361|  int i;
1362|
1363|  assert(len >= 0);
1364|
1365|  for (i = 0; i < len; i++) {
1366|    jv n = jv_array_get(jv_copy(j), i);
1367|    assert(JVP_HAS_KIND(n, JV_KIND_NUMBER));
