1392|jv jv_string_slice(jv j, int start, int end) {
1393|  assert(JVP_HAS_KIND(j, JV_KIND_STRING));
1394|  const char *s = jv_string_value(j);
1395|  int len = jv_string_length_bytes(jv_copy(j));
1396|  int i;
1397|  const char *p, *e;
1398|  int c;
1399|  jv res;
1400|
1401|  jvp_clamp_slice_params(len, &start, &end);
1402|  assert(0 <= start && start <= end && end <= len);
1403|
1404|  /* Look for byte offset corresponding to start codepoints */
1405|  for (p = s, i = 0; i < start; i++) {
1406|    p = jvp_utf8_next(p, s + len, &c);
1407|    if (p == NULL) {
1408|      jv_free(j);
1409|      return jv_string_empty(16);
1410|    }
1411|    if (c == -1) {
1412|      jv_free(j);
1413|      return jv_invalid_with_msg(jv_string("Invalid UTF-8 string"));
1414|    }
1415|  }
1416|  /* Look for byte offset corresponding to end codepoints */
1417|  for (e = p; e != NULL && i < end; i++) {
1418|    e = jvp_utf8_next(e, s + len, &c);
1419|    if (e == NULL) {
1420|      e = s + len;
1421|      break;
1422|    }
1423|    if (c == -1) {
1424|      jv_free(j);
1425|      return jv_invalid_with_msg(jv_string("Invalid UTF-8 string"));
1426|    }
1427|  }
1428|
1429|  /*
1430|   * NOTE: Ideally we should do here what jvp_array_slice() does instead
1431|   * of allocating a new string as we do!  However, we assume NUL-
1432|   * terminated strings all over, and in the jv API, so for now we waste
1433|   * memory like a drunken navy programmer.  There's probably nothing we
1434|   * can do about it.
1435|   */
1436|  res = jv_string_sized(p, e - p);
1437|  jv_free(j);
1438|  return res;
1439|}
