1469|jv jv_string_vfmt(const char* fmt, va_list ap) {
1470|  int size = 1024;
1471|  while (1) {
1472|    char* buf = jv_mem_alloc(size);
1473|    va_list ap2;
1474|    va_copy(ap2, ap);
1475|    int n = vsnprintf(buf, size, fmt, ap2);
1476|    va_end(ap2);
1477|    /*
1478|     * NOTE: here we support old vsnprintf()s that return -1 because the
1479|     * buffer is too small.
1480|     */
1481|    if (n >= 0 && n < size) {
1482|      jv ret = jv_string_sized(buf, n);
1483|      jv_mem_free(buf);
1484|      return ret;
1485|    } else {
1486|      jv_mem_free(buf);
1487|      size = (n > 0) ? /* standard */ (n * 2) : /* not standard */ (size * 2);
1488|    }
1489|  }
1490|}
