1504|#define JVP_FLAGS_OBJECT  JVP_MAKE_FLAGS(JV_KIND_OBJECT, JVP_PAYLOAD_ALLOCATED)
1505|
1506|struct object_slot {
1507|  int next; /* next slot with same hash, for collisions */
1508|  uint32_t hash;
1509|  jv string;
1510|  jv value;
1511|};
1512|
1513|typedef struct {
1514|  jv_refcnt refcnt;
1515|  int next_free;
1516|  struct object_slot elements[];
1517|} jvp_object;
