1520|/* warning: nontrivial justification of alignment */
1521|static jv jvp_object_new(int size) {
1522|  // Allocates an object of (size) slots and (size*2) hash buckets.
1523|
1524|  // size must be a power of two
1525|  assert(size > 0 && (size & (size - 1)) == 0);
1526|
1527|  jvp_object* obj = jv_mem_alloc(sizeof(jvp_object) +
1528|                                 sizeof(struct object_slot) * size +
1529|                                 sizeof(int) * (size * 2));
1530|  obj->refcnt.count = 1;
1531|  for (int i=0; i<size; i++) {
1532|    obj->elements[i].next = i - 1;
1533|    obj->elements[i].string = JV_NULL;
1534|    obj->elements[i].hash = 0;
1535|    obj->elements[i].value = JV_NULL;
1536|  }
1537|  obj->next_free = 0;
1538|  int* hashbuckets = (int*)(&obj->elements[size]);
1539|  for (int i=0; i<size*2; i++) {
1540|    hashbuckets[i] = -1;
1541|  }
1542|  jv r = {JVP_FLAGS_OBJECT, 0, 0, size, {&obj->refcnt}};
1543|  return r;
1544|}
