1579|static struct object_slot* jvp_object_find_slot(jv object, jv keystr, int* bucket) {
1580|  uint32_t hash = jvp_string_hash(keystr);
1581|  for (struct object_slot* curr = jvp_object_get_slot(object, *bucket);
1582|       curr;
1583|       curr = jvp_object_next_slot(object, curr)) {
1584|    if (curr->hash == hash && jvp_string_equal(keystr, curr->string)) {
1585|      return curr;
1586|    }
1587|  }
1588|  return 0;
