1591|static struct object_slot* jvp_object_add_slot(jv object, jv key, int* bucket) {
1592|  jvp_object* o = jvp_object_ptr(object);
1593|  int newslot_idx = o->next_free;
1594|  if (newslot_idx == jvp_object_size(object)) return 0;
1595|  struct object_slot* newslot = jvp_object_get_slot(object, newslot_idx);
1596|  o->next_free++;
1597|  newslot->next = *bucket;
1598|  *bucket = newslot_idx;
1599|  newslot->hash = jvp_string_hash(key);
1600|  newslot->string = key;
1601|  return newslot;
