1612|static void jvp_object_free(jv o) {
1613|  assert(JVP_HAS_KIND(o, JV_KIND_OBJECT));
1614|  if (jvp_refcnt_dec(o.u.ptr)) {
1615|    for (int i=0; i<jvp_object_size(o); i++) {
