1626|static jv jvp_object_rehash(jv object) {
1627|  assert(JVP_HAS_KIND(object, JV_KIND_OBJECT));
1628|  assert(jvp_refcnt_unshared(object.u.ptr));
1629|  int size = jvp_object_size(object);
1630|  jv new_object = jvp_object_new(size * 2);
1631|  for (int i=0; i<size; i++) {
1632|    struct object_slot* slot = jvp_object_get_slot(object, i);
1633|    if (jv_get_kind(slot->string) == JV_KIND_NULL) continue;
1634|    int* new_bucket = jvp_object_find_bucket(new_object, slot->string);
1635|    assert(!jvp_object_find_slot(new_object, slot->string, new_bucket));
1636|    struct object_slot* new_slot = jvp_object_add_slot(new_object, slot->string, new_bucket);
1637|    assert(new_slot);
1638|    new_slot->value = slot->value;
1639|  }
1640|  // references are transported, just drop the old table
1641|  jv_mem_free(jvp_object_ptr(object));
1642|  return new_object;
1643|}
