1645|static jv jvp_object_unshare(jv object) {
1646|  assert(JVP_HAS_KIND(object, JV_KIND_OBJECT));
1647|  if (jvp_refcnt_unshared(object.u.ptr))
1648|    return object;
1649|
1650|  jv new_object = jvp_object_new(jvp_object_size(object));
1651|  jvp_object_ptr(new_object)->next_free = jvp_object_ptr(object)->next_free;
1652|  for (int i=0; i<jvp_object_size(new_object); i++) {
1653|    struct object_slot* old_slot = jvp_object_get_slot(object, i);
1654|    struct object_slot* new_slot = jvp_object_get_slot(new_object, i);
1655|    *new_slot = *old_slot;
1656|    if (jv_get_kind(old_slot->string) != JV_KIND_NULL) {
1657|      new_slot->string = jv_copy(old_slot->string);
1658|      new_slot->value = jv_copy(old_slot->value);
1659|    }
1660|  }
1661|
1662|  int* old_buckets = jvp_object_buckets(object);
1663|  int* new_buckets = jvp_object_buckets(new_object);
1664|  memcpy(new_buckets, old_buckets, sizeof(int) * jvp_object_size(new_object)*2);
1665|
1666|  jvp_object_free(object);
1667|  assert(jvp_refcnt_unshared(new_object.u.ptr));
1668|  return new_object;
