1671|static jv* jvp_object_write(jv* object, jv key) {
1672|  *object = jvp_object_unshare(*object);
1673|  int* bucket = jvp_object_find_bucket(*object, key);
1674|  struct object_slot* slot = jvp_object_find_slot(*object, key, bucket);
1675|  if (slot) {
1676|    // already has the key
1677|    jvp_string_free(key);
1678|    return &slot->value;
1679|  }
1680|  slot = jvp_object_add_slot(*object, key, bucket);
1681|  if (slot) {
1682|    slot->value = jv_invalid();
1683|  } else {
1684|    *object = jvp_object_rehash(*object);
1685|    bucket = jvp_object_find_bucket(*object, key);
1686|    assert(!jvp_object_find_slot(*object, key, bucket));
1687|    slot = jvp_object_add_slot(*object, key, bucket);
1688|    assert(slot);
1689|    slot->value = jv_invalid();
1690|  }
1691|  return &slot->value;
1692|}
