1694|static int jvp_object_delete(jv* object, jv key) {
1695|  assert(JVP_HAS_KIND(key, JV_KIND_STRING));
1696|  *object = jvp_object_unshare(*object);
1697|  int* bucket = jvp_object_find_bucket(*object, key);
1698|  int* prev_ptr = bucket;
1699|  uint32_t hash = jvp_string_hash(key);
1700|  for (struct object_slot* curr = jvp_object_get_slot(*object, *bucket);
1701|       curr;
1702|       curr = jvp_object_next_slot(*object, curr)) {
1703|    if (hash == curr->hash && jvp_string_equal(key, curr->string)) {
1704|      *prev_ptr = curr->next;
1705|      jvp_string_free(curr->string);
1706|      curr->string = JV_NULL;
1707|      jv_free(curr->value);
1708|      return 1;
1709|    }
1710|    prev_ptr = &curr->next;
1711|  }
1712|  return 0;
1713|}
