1724|static int jvp_object_equal(jv o1, jv o2) {
1725|  int len2 = jvp_object_length(o2);
1726|  int len1 = 0;
1727|  for (int i=0; i<jvp_object_size(o1); i++) {
1728|    struct object_slot* slot = jvp_object_get_slot(o1, i);
1729|    if (jv_get_kind(slot->string) == JV_KIND_NULL) continue;
1730|    jv* slot2 = jvp_object_read(o2, slot->string);
1731|    if (!slot2) return 0;
