78|static void run_jq_tests(jv lib_dirs, int verbose, FILE *testdata, int skip, int take) {
79|  char prog[4096] = {0};
80|  char buf[4096];
81|  struct err_data err_msg;
82|  int tests = 0, passed = 0, invalid = 0;
83|  unsigned int lineno = 0;
84|  int must_fail = 0;
85|  int check_msg = 0;
86|  jq_state *jq = NULL;
87|
88|  int tests_to_skip = skip > 0 ? skip : 0;
89|  int tests_to_take = take;
90|
91|  jq = jq_init();
92|  assert(jq);
93|  if (jv_get_kind(lib_dirs) == JV_KIND_NULL)
94|    lib_dirs = jv_array();
95|  jq_set_attr(jq, jv_string("JQ_LIBRARY_PATH"), lib_dirs);
96|
97|  while (1) {
98|    if (!fgets(prog, sizeof(prog), testdata)) break;
99|    lineno++;
100|    if (skipline(prog)) continue;
101|    if (checkfail(prog)) {
102|      must_fail = 1;
103|      check_msg = checkerrormsg(prog);
104|      jq_set_error_cb(jq, test_err_cb, &err_msg);
105|      continue;
106|    }
107|    if (prog[strlen(prog)-1] == '\n') prog[strlen(prog)-1] = 0;
108|
109|    if (skip > 0) {
110|      skip--;
111|
112|      // skip past test data
113|      while (fgets(buf, sizeof(buf), testdata)) {
114|        lineno++;
115|        if (buf[0] == '\n' || (buf[0] == '\r' && buf[1] == '\n'))
116|          break;
117|      }
118|
119|      must_fail = 0;
120|      check_msg = 0;
121|
122|      continue;
123|    } else if (skip == 0) {
124|      printf("Skipped %d tests\n", tests_to_skip);
125|      skip = -1;
126|    }
127|
128|    if (take > 0) {
129|      take--;
130|    } else if (take == 0) {
131|      printf("Hit the number of tests limit (%d), breaking\n", tests_to_take);
132|      break;
133|    }
134|
135|    int pass = 1;
136|    tests++;
137|    printf("Test #%d: '%s' at line number %u\n", tests + tests_to_skip, prog, lineno);
138|    int compiled = jq_compile(jq, prog);
139|
140|    if (must_fail) {
141|      jq_set_error_cb(jq, NULL, NULL);
142|      if (!fgets(buf, sizeof(buf), testdata)) { invalid++; break; }
143|      lineno++;
144|      if (buf[strlen(buf)-1] == '\n') buf[strlen(buf)-1] = 0;
145|      if (compiled) {
146|        printf("*** Test program compiled that should not have at line %u: %s\n", lineno, prog);
147|        must_fail = 0;
148|        check_msg = 0;
149|        invalid++;
150|        continue;
151|      }
152|      if (check_msg && strcmp(buf, err_msg.buf) != 0) {
153|        printf("*** Erroneous test program failed with wrong message (%s) at line %u: %s\n", err_msg.buf, lineno, prog);
154|        invalid++;
155|      } else {
156|        passed++;
157|      }
158|      must_fail = 0;
159|      check_msg = 0;
160|      continue;
161|    }
162|
163|    if (!compiled) {
164|      printf("*** Test program failed to compile at line %u: %s\n", lineno, prog);
165|      invalid++;
166|      // skip past test data
167|      while (fgets(buf, sizeof(buf), testdata)) {
168|        lineno++;
169|        if (buf[0] == '\n' || (buf[0] == '\r' && buf[1] == '\n'))
170|          break;
171|      }
172|      continue;
173|    }
174|    if (verbose) {
175|      printf("Disassembly:\n");
176|      jq_dump_disassembly(jq, 2);
177|      printf("\n");
178|    }
179|    if (!fgets(buf, sizeof(buf), testdata)) { invalid++; break; }
180|    lineno++;
181|    jv input = jv_parse(buf);
182|    if (!jv_is_valid(input)) {
183|      printf("*** Input is invalid on line %u: %s\n", lineno, buf);
184|      invalid++;
185|      continue;
186|    }
187|    jq_start(jq, input, verbose ? JQ_DEBUG_TRACE : 0);
188|
189|    while (fgets(buf, sizeof(buf), testdata)) {
190|      lineno++;
191|      if (skipline(buf)) break;
192|      jv expected = jv_parse(buf);
193|      if (!jv_is_valid(expected)) {
194|        printf("*** Expected result is invalid on line %u: %s\n", lineno, buf);
195|        invalid++;
196|        continue;
197|      }
198|      jv actual = jq_next(jq);
199|      if (!jv_is_valid(actual)) {
200|        jv_free(expected);
201|        jv_free(actual);
202|        printf("*** Insufficient results for test at line number %u: %s\n", lineno, prog);
203|        pass = 0;
204|        break;
205|      } else if (!jv_equal(jv_copy(expected), jv_copy(actual))) {
206|        printf("*** Expected ");
207|        jv_dump(jv_copy(expected), 0);
208|        printf(", but got ");
209|        jv_dump(jv_copy(actual), 0);
210|        printf(" for test at line number %u: %s\n", lineno, prog);
211|        pass = 0;
212|      }
213|#ifdef USE_DECNUM
214|      jv as_string = jv_dump_string(jv_copy(expected), rand() & ~(JV_PRINT_COLOR|JV_PRINT_REFCOUNT));
215|      jv reparsed = jv_parse_sized(jv_string_value(as_string), jv_string_length_bytes(jv_copy(as_string)));
216|      assert(jv_equal(jv_copy(expected), jv_copy(reparsed)));
217|      jv_free(as_string);
218|      jv_free(reparsed);
219|#endif
220|      jv_free(expected);
221|      jv_free(actual);
222|    }
223|    if (pass) {
224|      jv extra = jq_next(jq);
225|      if (jv_is_valid(extra)) {
226|        printf("*** Superfluous result: ");
227|        jv_dump(extra, 0);
228|        printf(" for test at line number %u, %s\n", lineno, prog);
229|        pass = 0;
230|      } else {
231|        jv_free(extra);
232|      }
233|    }
234|    passed+=pass;
235|  }
236|  jq_teardown(&jq);
237|
238|  int total_skipped = tests_to_skip;
239|
240|  if (skip > 0) {
241|    total_skipped = tests_to_skip - skip;
242|  }
243|
244|  printf("%d of %d tests passed (%d malformed, %d skipped)\n",
245|    passed, tests, invalid, total_skipped);
246|
247|  if (skip > 0) {
248|    printf("WARN: skipped past the end of file, exiting with status 2\n");
249|    exit(2);
250|  }
251|
252|  if (passed != tests) exit(1);
253|}

281|static void test_jq_start_resets_state(char *prog, const char *input) {
282|  printf("Test jq_state: %s\n", prog);
283|  jq_state *jq = jq_init();
284|  assert(jq);
285|
286|  int compiled = jq_compile(jq, prog);
287|  assert(compiled);
288|
289|  // First call to jq_start. Run until completion.
290|  jv parsed_input = jv_parse(input);
291|  assert(jv_is_valid(parsed_input));
292|  jq_start(jq, parsed_input, 0);
293|  assert(test_start_state(jq, prog));
294|  while (1) {
295|    jv result = jq_next(jq);
296|    int valid = jv_is_valid(result);
297|    jv_free(result);
298|    if (!valid) { break; }
299|  }
300|
301|  // Second call to jq_start.
302|  jv parsed_input2 = jv_parse(input);
303|  assert(jv_is_valid(parsed_input2));
304|  jq_start(jq, parsed_input2, 0);
305|  assert(test_start_state(jq, prog));
306|
307|  jq_teardown(&jq);
308|}

