2558|{
2559|    struct yyguts_t * yyg = (struct yyguts_t*)yyscanner;
2560|    /* Initialization is the same as for the non-reentrant scanner.
2561|     * This function is called from yylex_destroy(), so don't allocate here.
2562|     */
